(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Аанг","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Крамарю! Аппа вже відпочив!"},{"a":"atlab_aang","t":"То... думаю, нам час прощатися..."},{"a":"atlab_sokka","t":"Гей, не сумуй! Ми будь-коли можемо повернутися!"},{"a":"atlab_aang","t":"Твоя правда! Пам'ятаєш цю дорогу, Сокко?"},{"a":"atlab_sokka","t":"Е-е-е... Та якось не звертав уваги..."},{"a":"atlab_sokka","t":"Б-байдуже! Нам час повертатися до своєї надважливої справи!"},{"a":"atlab_sokka","t":"Гей, Момо! Ми йдемо!"},{"a":"atlab_aang","t":"Момо! ...Момо?"},{"a":"atlab_aang","t":"Тобі тут подобається, так? Ясно, добре."},{"a":"atlab_aang","t":"Крамарю, наглядатимеш за Момо якийсь час, добре?"},{"a":"atlab_aang","t":"Я повернуся за тобою пізніше, Момо. Обіцяю!"},{"a":"atlab_aang","t":"Ходімо, Сокко. Дякую за все, крамарю!"},{"a":"atlab_sokka","t":"Бувай!"},{"a":"atlab_aang","t":"Давай, Аппа! Вйо, вйо!"}]},{"id":"atlab_aang_01","i":1,"title":"Доленосний поворот не туди","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"inn","t":"Вибач, малий, я не все зрозумів. Можеш повторити свою розповідь спочатку?"},{"a":"atlab_aang","t":"Перепрошую! З вашого дозволу розповім ще раз!"},{"a":"atlab_aang","t":"Я — Аанг, аватар."},{"a":"atlab_aang","t":"Ми з друзями подорожували на небесному зубрі..."},{"a":"atlab_aang","t":"Під час польоту ми, вочевидячки, не туди звернули, бо опинилися тут!"},{"a":"inn","t":"Цей здоровенний бицюга за вікном літає?"},{"a":"atlab_aang","t":"Так! Його звати Аппа. Він дуже дружній!"},{"a":"inn","t":"А ще, схоже, досить виснажений. За вами, хлопці, хтось женеться?"},{"a":"atlab_aang","t":"Ох, м-м-м..."},{"a":"inn","t":"Гей, не хвилюйся. Я нікому не дозволю кривдити моїх гостей. Даю слово Оскара."},{"a":"inn","t":"Скажіть мені, хлоп'ята, хочете залишитися тут безкоштовно?"},{"a":"atlab_aang","t":"Безкоштовно? Правда?!"},{"a":"inn","t":"Почнемо з того, що ваші чудернацькі гроші, схоже, тут ніц не варті."},{"a":"inn","t":"Не можу ж я дозволити, щоб купка дітлахів спала на вулиці, так?"},{"a":"atlab_aang","t":"Д-дякую вам, пане Оскаре!"},{"a":"inn","t":"Схоже, ви хлопці вправні. Може, натомість погодитеся допомогти моєму приятелю-крамарю?"},{"a":"atlab_aang","t":"Звичайно ж! Ми дуже вам вдячні!"}]},{"id":"atlab_aang_02","i":2,"title":"Можеш керувати вогнем?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"inn","t":"Привіт, Лілу! Познайомся з моїм новим приятелем!"},{"a":"lilu","t":"Привіт! Я ще ніколи не бачила таких татуювань, як у тебе..."},{"a":"atlab_aang","t":"Я — Аанг! А я ще ніколи не бачив такого капелюха, як у тебе!"},{"a":"inn","t":"Нумо, Аанг, покажи їй свій фокус!"},{"a":"atlab_aang","t":"Ти маєш на увазі... цей?"},{"a":"lilu","t":"Як ти це зробив? Я не відчула жодної магії!"},{"a":"atlab_aang","t":"Керування повітрям! Я також умію керувати землею і водою!"},{"a":"lilu","t":"Неймовірно! Зачекай, дай запишу..."},{"a":"lilu","t":"Можливо, це Ци? Ще ніколи не бачила, щоб хтось таке виробляв..."},{"a":"atlab_aang","t":"Усе правильно! Але на таке здатен не кожен. Треба мати природжений талант до цього мистецтва!"},{"a":"lilu","t":"Ти казав, що можеш керувати повітрям, землею і водою... А вогнем?"},{"a":"atlab_aang","t":"Ох... я... Я ще не опанував керування вогнем..."},{"a":"atlab_aang","t":"...Ніяк не можу знайти того, хто б мене навчив."},{"a":"lilu","t":"Ось як? А я трохи володію магією вогню!"},{"a":"lilu","t":"Це трохи інше, але ти, можливо, захочеш подивитися, як воно працює!"},{"a":"atlab_aang","t":"О... звичайно. Дякую, Лілу."}]},{"id":"atlab_aang_03","i":3,"title":"Останній повелитель повітря","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"elderowen","t":"Аангу, мій хлопчику. Як тобі міське життя?"},{"a":"atlab_aang","t":"Воно просто чудове, старійшино Оуене! Дякую за гостинність."},{"a":"elderowen","t":"Не варто подяки. А скажи-но мені, хлопчику, де твої батьки?"},{"a":"atlab_aang","t":"Ох... У мене... немає більше батьків."},{"a":"atlab_aang","t":"Мою сім'ю... усіх повітряних кочівників убили представники народу вогню."},{"a":"atlab_aang","t":"...Я один залишився живим."},{"a":"elderowen","t":"Боже милостивий! Співчуваю тобі, бідна дитино..."},{"a":"elderowen","t":"...Якщо вам із друзями нікуди повертатися, може, поселитеся тут?"},{"a":"elderowen","t":"Я впевнений, що мешканці міста будуть дуже раді, якщо ви залишитеся. Ви тут уже доволі популярні!"},{"a":"atlab_aang","t":"Дякую за щедру пропозицію, старійшино... але я не можу її прийняти."},{"a":"atlab_aang","t":"Як ми вже згадували, повелитель вогню Озай уже планує свій наступний крок."},{"a":"atlab_aang","t":"Коли комета Созіна знову осяє небо, народ вогню завоює мій світ..."},{"a":"atlab_aang","t":"...І Царство Землі... і племена води... зазнали тієї ж сумної долі, що й повітряні кочівники."},{"a":"atlab_aang","t":"Я як аватар єдиний, хто може його зупинити! ...Але я ще не готовий."},{"a":"elderowen","t":"Який жахливий тягар випав на долю дитини..."},{"a":"elderowen","t":"Знай, що ти за будь-яких обставин можеш розраховувати на цілковиту підтримку нашого міста."},{"a":"atlab_aang","t":"Дякую, старійшино. Ви всі й так уже багато для нас зробили!"},{"a":"atlab_aang","t":"Ми обов'язково завітаємо до вас усіх, коли все це скінчиться!"}]},{"id":"atlab_aang_04","i":4,"title":"Знамення Созіна","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"mana","t":"Аватар. Ось наші шляхи й перетнулися."},{"a":"atlab_aang","t":"Хто ти? Звідки ти мене знаєш?"},{"a":"mana","t":"Для третього ока аватар сяє, ніби той маяк."},{"a":"atlab_aang","t":"А, гадання... Це без мене!"},{"a":"mana","t":"На тебе, кого багато, але хто ще недостатньо цілісний..."},{"a":"mana","t":"Чекає запекла битва із повелителем вогню."},{"a":"atlab_aang","t":"Повелитель вогню Озай... Ти про нього знаєш?"},{"a":"mana","t":"Під пильним поглядом комети земля розірветься на клапті, а поля згорять на попіл!"},{"a":"atlab_aang","t":"Це я знаю! Але що ж мені робити?"},{"a":"mana","t":"Не можна порушувати хід долі."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"...Але той, кому вистачить сміливості, може потягнути за нитки й змінити його напрямок."},{"a":"mana","t":"Надзвичайне значення можуть мати малоймовірний союзник і нестійкий союз."},{"a":"atlab_aang","t":"Дякую, ворожко... Я обміркую твої слова."},{"a":"mana","t":"..."},{"a":"mana","t":"Будь хоробрим, аватаре. Залишайся вірним собі — і переможеш."}]}]},{"id":"argon","name":"Аргон","chapters":[{"id":"argon_01","i":1,"title":"Тінь короля","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"...А потім я вдарив Гібліна мечем! Ось так!"},{"a":"elderowen","t":"Ого, оце так історія, Аргоне!"},{"a":"elderowen","t":"Ех, запал молодості..."},{"a":"elderowen","t":"Маю сказати, з твого боку було дуже мило супроводити старика під час ранкової прогулянки."},{"a":"argon","t":"Дрібниці! Якщо я маю стати колись лицарем, я маю допомагати нужденним!"},{"a":"elderowen","t":"Як твій батько? Упевнений, ти станеш чудовим лицарем, хлопчик."},{"a":"elderowen","t":"А що, можливо, навіть потрапиш до охорони самого короля!"},{"a":"elderowen","t":"Згадали, а ось і він на ринку! Чому б не попроситися до нього?"},{"a":"argon","t":"ВАША ВЕЛИЧНОСТЕ! Я хотів би запропонувати вам свої послуги лицаря!"},{"a":"king","t":"Що це взагалі таке?! Сіє, розберися із цим простолюдином!"},{"a":"sia","t":"Звичайно, мій королю."},{"a":"sia","t":"Отже, хлопче. Що трапилося?"},{"a":"argon","t":"Ой! Я..."},{"a":"argon","t":"Я лицар! Я хочу стати Аргоном!"},{"a":"argon","t":"Ні, почекайте..."},{"a":"sia","t":"А в тебе є характер!"},{"a":"sia","t":"Якщо ти такий упевнений, приходь до мене наступного тижня в двір замка."},{"a":"sia","t":"А до того часу добряче потренуйся! Мені не потрібні ледарі серед лицарів короля..."}]},{"id":"argon_02","i":2,"title":"Час тренування","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Аргон, що ти робиш?"},{"a":"argon","t":"Добряче тренуюся. У мене нарешті з'явився шанс стати лицарем короля!"},{"a":"lilu","t":"Короля? Чи його таємничої радниці Сії?"},{"a":"argon","t":"Це її ім'я? Воно теж красиве!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Ох! Ні! Лише король має значення!"},{"a":"argon","t":"Я маю стати лицарем! Усе інше не має значення!"},{"a":"lilu","t":"Так... Зараз, я зцілю твої рани."},{"a":"argon","t":"Дякую... ой! Твоє закляття щось пече!"}]},{"id":"argon_03","i":3,"title":"Дві сторони монети","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Добре! Сія з'явиться в будь-який момент!"},{"a":"argon","t":"Моє тренування не пройшло дарма, я готовий!"},{"a":"argon","t":"...Але я все одно щось дуже нервуюся..."},{"a":"argon","t":"А, привіт! Ти, у кущах!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Ти також хочеш стати лицарем?"},{"a":"argon","t":"Сія скоро з'явиться! Не треба ховатися, вона досить гарна!"},{"a":"yami","t":"Сіє!.."},{"a":"yami","t":"Мені треба йти. Бувай."},{"a":"argon","t":"С-стій!"},{"a":"argon","t":"Ого! Димова бомба?!"},{"a":"argon","t":"Яка дивна дівчина..."},{"a":"sia","t":"Хлопче, з ким ти розмовляєш?"},{"a":"argon","t":"А, Сія! Та я просто проходив тут поряд! Не звертайте уваги!"},{"a":"sia","t":"...Бачу. Що ж, здається, твоя рішучість залишилася."},{"a":"sia","t":"Ти готовий ризикнути життям як лицар короля?"},{"a":"argon","t":"Ще б пак! Тобто, звичайно! Батько пишатиметься мною!"},{"a":"sia","t":"Добре. У мене є перше завдання для тебе. Скоро відбудеться важлива подія..."}]},{"id":"argon_04","i":4,"title":"З пустими руками","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Ти жартуєш!"},{"a":"sia","t":"Ти загнав убивцю в кут... і не зміг її зупинити."},{"a":"sia","t":"Більше того, ти кажеш, що ВІДПУСТИВ її, оскільки вона хороша людина?!"},{"a":"argon","t":"..."},{"a":"sia","t":"Що за дурниці?"},{"a":"sia","t":"Ти РОЗУМІЄШ, що ця вбивця намагалася вбити нашого короля? Особу, яку ти присягнув захищати?"},{"a":"sia","t":"Ця подія наражає на небезпеку те, що твій кволий розум навіть не може зрозуміти."},{"a":"sia","t":"Ох... Гадаю, що останнє слово щодо звільнення лицарів має сказати сам король..."},{"a":"sia","t":"...Але не думай, що я тебе захищатиму. Можеш іти."},{"a":"argon","t":"..."},{"a":"argon","t":"О ні..."},{"a":"argon","t":"Вибач, тату."}]},{"id":"argon_a","i":4,"title":"Вежа титанів","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"elderowen","t":"Вежа титанів?"},{"a":"lilu","t":"Просимо, розкажіть нам усе про неї!"},{"a":"argon","t":"Я чув, як деякі герої про неї шепталися, але ніхто її навіть не бачив..."},{"a":"elderowen","t":"Насправді, Вежа титанів — міфічне місце. Ніхто достеменно не знає, чи воно існує насправді."},{"a":"elderowen","t":"Як кажуть, вона з'являється з нізвідки, щоб наймогутніші герої піднімалися її нескінченними сходами..."},{"a":"elderowen","t":"...А потім вона раптово зникає разом зі спогадами тих, хто міг її бачити."},{"a":"argon","t":"З-зі спогадами?"},{"a":"lilu","t":"Це дивно... а звідки тоді походять легенди?"},{"a":"argon","t":"Точно! Хтось же мав запам'ятати!"},{"a":"elderowen","t":"Говорять, що тих, хто проходить випробування титана, вежа вважає гідними."},{"a":"elderowen","t":"Ці герої повертаються... зміненими через отриманий досвід, і залишають свої спогади."},{"a":"elderowen","t":"Точніше — частина них залишається у вежі, а частина вежі залишається з ними."},{"a":"elderowen","t":"...Досить історій на сьогодні. Дякую, що послухали розповіді старика."},{"a":"lilu","t":"Ого! Цікаво, чи існує вона насправді?"},{"a":"argon","t":"Ага, я б хотів дослідити таке підземелля!"},{"a":"lilu","t":"Але ось що мене дивує... Звідки старійшина Оуен усе це знає?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Мандрівний лицар","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Ех..."},{"a":"steel","t":"Та це ж Аргон! Як справи?"},{"a":"argon","t":"О, привіт, Броме... Є робота для мене?"},{"a":"steel","t":"Сьогодні нічого, сер лицарю! Що сталося?"},{"a":"argon","t":"Тепер я просто Аргон. Я... утратив титул."},{"a":"steel","t":"Як прикро..."},{"a":"steel","t":"«Що б не трапилося, треба мислити позитивно! Ти все зможеш!»"},{"a":"steel","t":"Я впевнений, що вдача скоро до тебе повернеться!"},{"a":"argon","t":"Так... Дякую, Броме."},{"a":"argon","t":"А поки... я повештаюся міською площею."},{"a":"argon","t":"Ех..."}]},{"id":"argon_b","i":5,"title":"Ми титани?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"lilu","t":"Доброго ранку... Аргоне."},{"a":"argon","t":"(Зіває) Доброго."},{"a":"lilu","t":"...Ти також це відчуваєш?"},{"a":"argon","t":"Так, я втомлений! Ніби брав участь у квестах усю ніч!"},{"a":"lilu","t":"Дивись, і твій щит весь побитий!"},{"a":"argon","t":"А? Ти маєш рацію! Можу присягнути, що він ще вчора був чистесенький..."},{"a":"lilu","t":"Аргоне... Ти думаєш?.."},{"a":"polonia","t":"Гей! Комусь із вас, сухопутних, потрібні <c1>поножі Джаггернаута</c1>?"},{"a":"lilu","t":"Ні... тим більше не двадцять штук! Звідки все це в тебе?!"},{"a":"polonia","t":"Хех! А в чому справа? Гадки не маю."},{"a":"polonia","t":"Здається, я збираю здобич уві сні. Мабуть, це моя піратська душа виривається, арр."},{"a":"lilu","t":"І та дивна піратка теж..."},{"a":"lilu","t":"...Ми що, пройшли випробування вежі, і забули про це?.."},{"a":"argon","t":"Це означає, що ми були недостатньо сильними..."},{"a":"argon","t":"Я добре підготуюся до наступного разу! Ось побачиш!"}]},{"id":"argon_06","i":6,"title":"Другий шанс","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Отже... Ваша вбивця була в руках у цього «лицаря»..."},{"a":"sia","t":"...І він її відпустив, уважаючи її доброю людиною!"},{"a":"king","t":"Неймовірно! Здається, цей новий лицар — перспективний малий!"},{"a":"sia","t":"При всій повазі, мій королю..."},{"a":"sia","t":"Цей чоловік не зміг зупинити вашу вбивцю через якісь передчуття."},{"a":"king","t":"Саме так поводився б <c1>паладин</c1>, чи не так?"},{"a":"sia","t":"Прошу?"},{"a":"king","t":"Тримати супротивника в руках і бачити більше, ніж просто сварка й конфлікт..."},{"a":"king","t":"...А потім відпустити його та бути настільки впевненим у його виправленні, щоб ризикнути власним титулом."},{"a":"king","t":"Неймовірний зразок хоробрості та добросердя!"},{"a":"sia","t":"Я... маю сказати, що не дивилася на це з такого боку, мій королю."},{"a":"sia","t":"Але королівство вже десятки років не бачило появи паладина..."},{"a":"sia","t":"Мені скликати раду лицарів для обговорення цієї справи?"},{"a":"king","t":"Нісенітниця! Я сам уладнаю всі формальності."},{"a":"sia","t":"Як побажаєте, мій королю. Я негайно підготую ескорт."},{"a":"king","t":"Немає потреби. Я буду обережним, наче метелик!"}]},{"id":"argon_07","i":7,"title":"Непомітний король","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"king","t":"З дороги, бідното! Тут іде звичайний робітник!"},{"a":"tavern","t":"А, король Рейнгольд! Давно не бачилися. Відкрити для вас барило амброзії?"},{"a":"king","t":"Тсс! Я сьогодні непомітний! Не звертай на мене уваги!"},{"a":"tavern","t":"Так, звичайно! Який я дурний!"},{"a":"king","t":"Ей ти! Той, що ховається за прилавком!"},{"a":"argon","t":"Ой, вибачте, Ваша Величносте. Я вже йду..."},{"a":"king","t":"Дурниці! Майбутній паладин має право сидіти поряд з моєю сяючою величністю!"},{"a":"argon","t":"Сидіти поряд... Паладин?!"},{"a":"king","t":"Саме так! Моя безмежна мудрість бачить у тобі великий потенціал!"},{"a":"king","t":"Незважаючи на твої... незвичайні методи, твоє серце є чистим, а твоє почуття справедливості... захоплює!"},{"a":"king","t":"Тому королівство вважає, що ти гідний пройти випробування паладина!"},{"a":"argon","t":"Випробування паладина... Оце так!"},{"a":"argon","t":"Я все про це знаю! Кожне випробування є унікальним, а його результат визначає сам паладин..."},{"a":"argon","t":"Це має бути небезпечне завдання, наприклад убити дракона... або знищити небезпечний артефакт..."},{"a":"king","t":"Саме так! Це може бути будь-який достатньо відважний і самовідданий учинок заради королівства!"},{"a":"argon","t":"Я розумію! Дякую, Ваша Величносте! Ви не пошкодуєте!"},{"a":"king","t":"Звичайно, не пошкодую. Я ж завжди правий!"},{"a":"king","t":"...А тепер, оскільки я вже під прикриттям..."},{"a":"king","t":"Ей ти, старий! Навчи мене грати в карти!"},{"a":"master","t":"У карти? Старий Теодор грає лише з високими ставками..."}]},{"id":"argon_08","i":8,"title":"Новий вогонь","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Аргоне! Що за метушня?"},{"a":"argon","t":"Лілу, я стану паладином!"},{"a":"lilu","t":"Паладином! Н-неймовірно, Аргоне! Як?.."},{"a":"argon","t":"Король сказав мені пройти випробування! Це єдиний спосіб стати гідним титулу паладина."},{"a":"lilu","t":"Випробування... А ти знаєш, що робити?"},{"a":"argon","t":"..."},{"a":"argon","t":"О, ні! Гадки не маю!"},{"a":"argon","t":"Це має бути щось епічне, славетних масштабів..."},{"a":"lilu","t":"Аргон, ти ж і так славетний! Ти скрізь долаєш монстрів..."},{"a":"argon","t":"Авжеж, але це має бути щось більше..."},{"a":"argon","t":"Я чув, що на піку Похмурий Шпиль є демони з пір'ям. Можливо, це..."},{"a":"lilu","t":"Що б там не було, я знаю, що ти впораєшся!"},{"a":"argon","t":"Дякую, Лілу... Навіть коли я вже не був лицарем, ти продовжувала в мене вірити..."},{"a":"lilu","t":"Та це дрібниці!"},{"a":"lilu","t":"Як би там не було, тобі знадобиться допомога у твоєму квесті! Я приготую для тебе кілька сувоїв зцілення!"},{"a":"argon","t":"Чудово! За справу!"}]},{"id":"argon_09","i":9,"title":"Зіткнення на Похмурому Шпилі (Аргон)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Фу... Тут якось не дуже!"},{"a":"argon","t":"Скільки вже лізу й жодної гарпії навкруги... Навіть потрапив у засідку вбивць!"},{"a":"argon","t":"...Вони чимось схожі на ту дівчину-ніндзя."},{"a":"argon","t":"Добре, що Лілу дала мені ці сувої зцілення, фух!"},{"a":"argon","t":"Думаю, треба зробити перерву."},{"a":"argon","t":"А?"},{"a":"yami","t":"Знову ти."},{"a":"argon","t":"У-убивця короля!"},{"a":"argon","t":"Мабуть, це доля. Це доручення навіть краще за гарпію!"},{"a":"yami","t":"...Давай. Я вб'ю тебе просто на місці."}]},{"id":"argon_10a","i":10,"title":"Тріумфальне повернення","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Король Рейнгольд! Квест завершено!"},{"a":"king","t":"Чудово! Яку огидну тварюку ти вбив?"},{"a":"argon","t":"Ммм... тут така справа..."},{"a":"yami","t":"...Вітаю."},{"a":"king","t":"Щ-що це взагалі таке?!"},{"a":"sia","t":"Охорона! Арештуйте їх обох!"},{"a":"argon","t":"Ой! Зачекайте! Вона почала нове життя!"},{"a":"king","t":"Ось як?"},{"a":"yami","t":"Я прийшла... вибачитись."},{"a":"sia","t":"Мій король, звичайно, ви не будете вірити..."},{"a":"argon","t":"Я можу за неї поручитися. Честю лицаря!"},{"a":"king","t":"Дуже добре! Я її вислухаю!"},{"a":"sia","t":"Ох... Цього я й боялася."},{"a":"sia","t":"Охорона! Приведіть підкріплення та спостерігайте за кожним її рухом!"},{"a":"sia","t":"Аргоне, почекай за дверима, поки ми поговоримо про це із... цим незваним гостем."},{"a":"argon","t":"Зрозуміло!"},{"a":"argon","t":"(Невже я так помилився?)"}]},{"id":"argon_10b","i":11,"title":"Спокута","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Ух... Ще цього головного болю мені не вистачало. "},{"a":"argon","t":"Леді Сіє! Як усе пройшло?"},{"a":"sia","t":"...Усупереч усьому, король Рейнгольд готовий вибачити свою потенційну вбивцю."},{"a":"sia","t":"Хоча я не схильна так просто довіряти, вона поділилася цінною інформацією про свій азумський орден."},{"a":"argon","t":"Т-тобто це означає!.."},{"a":"sia","t":"Так, ми приймемо її капітуляцію та вибачення."},{"a":"sia","t":"Наразі вона під наглядом лікарів через виснаження, але має повністю видужати."},{"a":"sia","t":"Щодо тебе, паладине Аргоне..."},{"a":"argon","t":"П-паладин!"},{"a":"sia","t":"Так, знищити загрозу — це гідний учинок, але сприяти спокуті затятого ворога королівства..."},{"a":"sia","t":"Здається, урешті-решт, король Рейнгольд був правий щодо тебе."},{"a":"sia","t":"А тепер іди й святкуй, паладине. Упевнена, скоро в тебе буде багато роботи!"},{"a":"argon","t":"Саме так! Дякую!"},{"a":"argon","t":"Тато... Сподіваюсь, ти пишаєшся."}]},{"id":"argon_epilogue","i":12,"title":"Епілог","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"П-паладин?! Ти впорався, Аргоне!"},{"a":"argon","t":"На мить я подумав, що все зіпсував..."},{"a":"argon","t":"Але тато був правий. Усе, що треба робити, — іти за позовом серця!"},{"a":"lilu","t":"Ах... А це означає, що тебе відправлять у похід за моря?"},{"a":"argon","t":"Ще ні. Леді Сія сподівається, що я зможу навчити героїв стати паладинами."},{"a":"lilu","t":"О! Як добре!.. Хоча мені складно уявити тебе в ролі вчителя."},{"a":"lilu","t":"А ти не будеш займатися суперважливими паладинськими квестами?"},{"a":"argon","t":"Зроблю все можливе! Королівство на мене розраховує!"},{"a":"tavern","t":"Привіт, шляхетний паладине!"},{"a":"tavern","t":"Бром сказав мені, що йому потрібні ще рукавиці плавильника!"},{"a":"argon","t":"Так! Зараз!"},{"a":"lilu","t":"...Є речі, які не змінюються, так?"},{"a":"tavern","t":"Аргон точно з таких."}]},{"id":"argon_c","i":13,"title":"Увічнено в камені","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Зілля... не спрацювало, так?"},{"a":"lilu","t":"Ех... Ми так старалися..."},{"a":"lilu","t":"Вибачай, Аргоне. У мене не вийшло... Хоча б тобі там було не дуже дискомфортно."},{"a":"elderowen","t":"Гм-м... погані новини."},{"a":"lilu","t":"У нас ще є деякі варіанти, але..."},{"a":"lilu","t":"Без нього як без рук."},{"a":"elderowen","t":"Місто немов спорожніло тепер, розумієш?"},{"a":"lilu","t":"Таке відчуття, що сидиш на вечірці, де нікого не знаєш."},{"a":"lilu","t":"Ходіння туди-сюди його не поверне. Я повернуся до цього питання."},{"a":"lilu","t":"Може, Донован зможе допомогти."},{"a":"lilu","t":"Це обійдеться нам в деякі гроші."},{"a":"lilu","t":"Знаю, що ти й так нікуди не підеш, але все ж дочекайся. Ми тебе врятуємо!"},{"a":"argon_stone","t":"..."}]}]},{"id":"bjorn","name":"Бйорн","chapters":[{"id":"bjorn_01","i":1,"title":"Тато вдома","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"bjorn","t":"Малеча! Тато прийшов!"},{"a":"steel","t":"Тато!"},{"a":"wood","t":"...Тато."},{"a":"bjorn","t":"Що з обличчям, Горза?"},{"a":"wood","t":"Тебе місяцями не було з нами!"},{"a":"bjorn","t":"Таке життя рейнджера! На свіжому повітрі, далеко від дому."},{"a":"wood","t":"Пф-ф. Частіше навідуватися додому не завадило би."},{"a":"bjorn","t":"Якби я міг! Але у вулкана Попелястого озера свої плани!"},{"a":"wood","t":"У вулкана? Пам'ятаю, ти щось казав про справи на Похмурому Шпилі..."},{"a":"bjorn","t":"...Невже?"},{"a":"bjorn","t":"Напевно я щось наплутав! Хах!"},{"a":"bjorn","t":"Добре, проїхали. Я вам сувеніри привіз! Мерщій сюди!"},{"a":"steel","t":"О! Хай би це була нищівна іграшка!"}]},{"id":"bjorn_a","i":1,"title":"Найкращий друже Бамхам","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"bjorn","t":"Так, малеча, приглянете за Бамхамом, добре?"},{"a":"wood","t":"За цим грізним кабаном? Ні за що. Тримай його при собі."},{"a":"steel","t":"Па, не ображайся, але хіба він не... шалений?"},{"a":"bjorn","t":"О! Що ви таке кажете! Він же миленький!"},{"a":"wood","t":"Тато, він впадає у вбивчу лють, коли ти його відпускаєш."},{"a":"bjorn","t":"То було випадково. Він просто трошки... перехвилювався."},{"a":"wood","t":"А як же усі інші рази?"},{"a":"bjorn","t":"То також... випадково. Малюк Бамхам й мухи не образить!"},{"a":"wood","t":"Ще як образить та з превеликим задоволенням."},{"a":"wood","t":"Слухай, тато, як будеш у місті, краще тобі тримати цю штуку при собі."},{"a":"steel","t":"...Для безпеки усіх навколо."},{"a":"bjorn","t":"Ладно, ладно. Зрозумів. Усе нормально, Бамхаме. Я тебе люблю."},{"a":"bjorn","t":"Уоу, уоу, уоу! Тихіше, Бамхаме!"}]},{"id":"bjorn_02","i":2,"title":"Бйорн і покупка їжі","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"bjorn","t":"Дякую всім за теплий прийом! Як добре повернутися!"},{"a":"elderowen","t":"Ми раді, що ти повернувся цілим. Тебе не було багато місяців, і ми боялися найгіршого..."},{"a":"bjorn","t":"Простіть мене! Але таке життя рейнджера! Хах!"},{"a":"oils","t":"Знаючи тебе, ти вже, напевно, про свій наступний похід мрієш!"},{"a":"bjorn","t":"Хах! В яблучко! Більше того — ми виїжджаємо вже завтра на світанку!"},{"a":"oils","t":"Ніколи не міняйся, Бйорн. Обіцяю дивитися за Бромом та Горзою, коли тобі не стане."},{"a":"oils","t":"...Якщо на шляху зустрінеш гриби, що світяться, принесеш мені декілька?"},{"a":"bjorn","t":"Авжеж! Жодних проблем!"},{"a":"elderowen","t":"О... останнім часом у мене болить спина. Може принесеш ще трохи крижаних перлів?.."},{"a":"bjorn","t":"Невеличка задача. Я пошукаю, старійшина."},{"a":"engineer","t":"О! Бйорне! Мені ще луски іржавого змія знадобляться для нового рецепта, якщо можна!"},{"a":"bjorn","t":"Добре, добре! Записав."},{"a":"bjorn","t":"Фух!.. Здається, нам знадобляться додаткові сумки, Бамхаме!"}]},{"id":"bjorn_03","i":3,"title":"Усе, що пахне, то золото","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"bjorn","t":"Гм-м... Ти теж відчуваєш цей запах, Бамхаме?"},{"a":"bjorn","t":"Так, вірно. Метал. Сміття, вірогідно. Вперед, Бамхаме, на пошуки для мене!"},{"a":"bjorn","t":"Гарний хлоп'яга, так, подивимося..."},{"a":"bjorn","t":"Гм. Дивний прилад. Не думаю, що його випадково тут залишили..."},{"a":"bjorn","t":"Б'юся об заклад, якщо я трохи посмикаю цю ручку..."},{"a":"bjorn","t":"Гм-м... так, як і очікувалося..."},{"a":"bjorn","t":"...Вона зламається. Напевно, ми ще не так багато знаємо, а? Хах!"},{"a":"bjorn","t":"Але думаю, в нас є зачіпка. Ми шукали усюди кілька місяців, і минулого разу цієї речі там не було."},{"a":"bjorn","t":"Краще повернутися та запитати професіонала. Я не дружу з приладами!"}]},{"id":"bjorn_04","i":4,"title":"Дивний маяк","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"engineer","t":"Яке дивне місце! Ніколи нічого подібного не бачив!"},{"a":"engineer","t":"Тут нібито магія поєдналася з наукою і створила... маяк? Радар?"},{"a":"engineer","t":"Кажеш, знайшли вже зламаним?"},{"a":"bjorn","t":"Так. Яка погана вдача, так? Хах!"},{"a":"engineer","t":"Як прикро. Я мало що можу сказати: лише те, що він надсилає якусь інформацію."},{"a":"engineer","t":"Знаєш що, якщо почекаєш трошки, зроблю тобі пристрій, що показував би інші... ну-у... ці, «магічні маячки»."},{"a":"bjorn","t":"Прекрасно! Готовий йти далі, Бамхаме?"},{"a":"bjorn","t":"Ми не знаємо, що це за штуки... але точно нічого доброго."},{"a":"bjorn","t":"Наша задача дізнатися, хто за цим стоїть!"},{"a":"engineer","t":"Удачі! І... будьте обережні, стікаючись з чарівними технологіями!"}]}]},{"id":"donovan","name":"Донован","chapters":[{"id":"donovan_01","i":1,"title":"Оригінальний рецепт","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"herbalist","t":"Ласкаво прошу до магазину медичних товарів Марібель. Чим можу бути корисною?"},{"a":"donovan","t":"Пані Марібель, якщо не помиляюся? Я хотів особисто похвалити ваше останнє творіння."},{"a":"donovan","t":"Як винахідник зілля відновлення скажу, що ваше видозмінене креслення просто геніальне!"},{"a":"donovan","t":"Одна щіпка туманоквіту — а таке неймовірне покращення!"},{"a":"herbalist","t":"Хвилинку... Так ви — ТОЙ САМИЙ Донован? Неймовірно!"},{"a":"herbalist","t":"Креслення зілля відновлення винайдено приблизно 700 років тому..."},{"a":"herbalist","t":"Навіть як для ельфа ви виглядаєте щонайбільше на 150!"},{"a":"donovan","t":"Ви — сама люб'язність, пані Марібель."},{"a":"donovan","t":"Скажімо так, не всі мої креслення продаються..."},{"a":"donovan","t":"Але я впевнений, що такий майстерний алхімік, як ви, легко їх запам'ятає."},{"a":"donovan","t":"То я можу поглянути на цей туманоквіт?"}]},{"id":"donovan_02","i":2,"title":"Земля достатку","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"donovan","t":"Цікаво... Навіть звичайні яблука в цих місцях мають відмінну якість."},{"a":"donovan","t":"І як воно так виходить?.."},{"a":"lilu","t":"Якщо хтось і може це пояснити, то лише Джуніпер."},{"a":"lilu","t":"Ой, перепрошую! Я не хотіла втручатися у вашу розмову з тим... деревом."},{"a":"donovan","t":"Ах, панночка в капелюсі із широкими полями і її вірна сова..."},{"a":"donovan","t":"Ви, безсумнівно, міс Лілу."},{"a":"lilu","t":"Саме так! Та й вас, пане Доноване, усі тут знають!"},{"a":"donovan","t":"Я багато чув про юну обдаровану ученицю, яка мешкає в цьому місті, і теж радий знайомству."},{"a":"donovan","t":"То що ви казали, пані Лілу?.."},{"a":"lilu","t":"О, так! Джуніпер весь час говорить про те, що земля навколо міста кипить життям..."},{"a":"lilu","t":"Це, за її словами, одна з причин, чому їй так подобається тут вирощувати рослини."},{"a":"lilu","t":"А я як раз до печер Аврори йду. Приємно було побачитися, пане Доноване!"},{"a":"donovan","t":"Сподіваюся, ми ще зустрінемося."},{"a":"donovan","t":"Хм-м-м... Схоже, цій панночці щось відомо..."},{"a":"donovan","t":"Керн... виснажений... А в цьому королівстві, схоже, усе буяє."},{"a":"donovan","t":"Треба буде відвідати цю садівницю. Якщо тутешні інгредієнти сильніші..."},{"a":"donovan","t":"...Я маю цим скористатися."}]},{"id":"donovan_03","i":3,"title":"Під маскою","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Кликали мене, пані Сіє?"},{"a":"sia","t":"А, Лілу. Дякую, що так швиденько прийшла."},{"a":"sia","t":"...Певно, ти вже познайомилася з Донованом?"},{"a":"lilu","t":"О, так! Він легенда серед алхіміків! Я дуже рада, що ми зустрілися!"},{"a":"sia","t":"Будь із цією людиною дуже обережна."},{"a":"lilu","t":"Оце так! Але ж він такий джентльмен! Ще й дуже обізнаний..."},{"a":"sia","t":"Зовнішність іноді оманлива. За його юнацьким виглядом приховується тисячолітній хитрий геній."},{"a":"lilu","t":"Тисячолітній?! Це неймовірно навіть для ельфів! Думаєте..."},{"a":"sia","t":"Так. Не виключено, що він винайшов щось на кшталт еліксиру безсмертя."},{"a":"lilu","t":"Овва! Я б теж додала цей рецепт до свого гримуару!"},{"a":"sia","t":"Як і багато правителів. Підозрюю, що імператор Керну танцює під його дудку."},{"a":"lilu","t":"...Політика — штука складна."},{"a":"lilu","t":"Але дякую! Я буду з ним обережна!"},{"a":"sia","t":"Я знала, що ти зрозумієш."},{"a":"sia","t":"Щодо мене, то я постараюся, щоб він тримався подалі від нашого... чутливого короля."},{"a":"lilu","t":"Так... можливо, це найліпший варіант."}]},{"id":"donovan_a","i":3,"title":"Десять золотих — це грабунок","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"leather","t":"Привіт, спеціалісте із зілля. Маєш хвилинку?"},{"a":"donovan","t":"От... ці волоцюги."},{"a":"donovan","t":"Із ким маю... честь?.."},{"a":"leather","t":"Я — Тамас, шкіряник."},{"a":"leather","t":"Чув, ти можеш приготувати крутий еліксир безсмертя, друже. Можна й мені пляшечку?"},{"a":"donovan","t":"...Я й не втямлю, де це ви таке почули."},{"a":"donovan","t":"Навіть якби це було й правдою, запевняю, що я б не віддав вам таку цінність."},{"a":"leather","t":"Я дам тобі за нього десять золотих."},{"a":"donovan","t":"Виключено. За цей рецепт велися війни! Імператори зі всього світу благають хоча б крапельку!"},{"a":"leather","t":"А ти вмієш торгуватися, друже. Добре, п'ятнадцять золотих. Але більше й не проси."},{"a":"donovan","t":"У тебе від запаху шкіри вже зовсім макітра не варить, волоцюго? Цей рецепт я не розкрию за все золото світу!"},{"a":"donovan","t":"Мені пора. Прошу більше ніколи до мене не звертатися."},{"a":"leather","t":"Ех, мало не вигоріло."},{"a":"leather","t":"...Мабуть, доведеться знайти для овець інше частування."}]}]},{"id":"ashley","name":"Ешлі","chapters":[{"id":"ashley_01","i":1,"title":"Незвичайний самурай","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Справжній самурай!.. Не можу дочекатися!"},{"a":"argon","t":"Панночка-самурайка! Я — Аргон, майбутній ли..."},{"a":"ashley","t":"Здоровченко. Я — Ешлі. Як справи?"},{"a":"argon","t":"Здо-ровченко?"},{"a":"tavern","t":"Прибери ноги зі столу, будь ласка!"},{"a":"ashley","t":"От ще. Добре."},{"a":"ashley","t":"Ну? Що тобі треба?"},{"a":"argon","t":"Е-е-е... Я думав, самураї зазвичай організованіші і все таке. Ні?"},{"a":"ashley","t":"Що? Так, братва вдома була досить занудною в цьому плані."},{"a":"ashley","t":"Тепер я вільна. Просто ронін. Самурай без господаря."},{"a":"argon","t":"Розумію... О, згадав!"},{"a":"argon","t":"У нас із Лілу був запланований квест у Замку з привидами, але..."},{"a":"argon","t":"Дещо намітилося в тренувальному залі! Можеш мене замінити?"},{"a":"ashley","t":"Звичайно. Але ти будеш мені винен, лицарику."}]},{"id":"ashley_02","i":2,"title":"Озброєна й готова","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"Ти ж Лілу, так?"},{"a":"lilu","t":"Правильно! Приємно познайомитися!"},{"a":"ashley","t":"Ну що ж, тоді ходімо."},{"a":"lilu","t":"З-зачекай! Стій!"},{"a":"lilu","t":"Ми ж нічого не підготували! Зілля, пайки і..."},{"a":"ashley","t":"Пайки-шмайки... Нічого нам не потрібно."},{"a":"ashley","t":"Ми виживемо або помремо. Третього варіанту немає."},{"a":"lilu","t":"Це... ні! Це вкрай необачно!"},{"a":"ashley","t":"То я пішла. Сюди?"},{"a":"lilu","t":"Ні! Це виючий ліс..."},{"a":"argon","t":"Е-е-е... Щасти..."}]},{"id":"ashley_03","i":3,"title":"На грані життя","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"І це все, на що ви, монстри, здатні? ДАВАЙТЕ!"},{"a":"lilu","t":"Ешлі! Прошу, повільніше! Я не встигаю тебе зцілювати!"},{"a":"ashley","t":"Це... усе... ДРІБНИЦІ!!!"},{"a":"ashley","t":"Хух... Класний брухт, правда?"},{"a":"lilu","t":"Ти що, жартуєш?! Ти мало не загинула!"},{"a":"lilu","t":"Не дивно, що ти втратила руку, якщо так поводишся!"},{"a":"ashley","t":"Дурниці. Там усе інакше було."},{"a":"ashley","t":"Такої помилки... я більше не повторю."},{"a":"lilu","t":"Гм. Цього разу я зцілюватиму без знеболювального."},{"a":"lilu","t":"Сама винна. Зберися з духом."},{"a":"ashley","t":"Ха-ха... ха... я витримаю..."},{"a":"ashley","t":"Ой! Ой-ой-ой..."}]},{"id":"ashley_a","i":4,"title":"Знайомі відчуття","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"ashley","t":"Здоровченко. Що це тут за маленькі монстрики?"},{"a":"elven","t":"Це мої дорогенькі фамільяри. Ласкаво прошу."},{"a":"elven","t":"Гідним захисникам я дозволяю взяти одного з них за відданого товариша."},{"a":"ashley","t":"О. Домашні тварини, так? Розумію."},{"a":"ashley","t":"Добре. Ти, зелененький. Я називатиму тебе <c1>Хитрюгою</c1>. Ходімо зі мною."},{"a":"ashley","t":"А ти симпатичний, <c1>Сніжку</c1>. Я тебе понесу."},{"a":"elven","t":"Ох... Боюся, що..."},{"a":"ashley","t":"Ух ти, яка потворна пташка!"},{"a":"ashley","t":"Я назву тебе <c1>Горобчик</c1>. Ти теж можеш піти зі мною."},{"a":"elven","t":"...Зрозуміло. Бажаю всім вам гарно розважитися."}]},{"id":"ashley_04","i":5,"title":"Квест провалено успішно","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Як учорашній квест? Лілу трохи засмучена..."},{"a":"ashley","t":"Я повернулася жива та здорова. Нажаль."},{"a":"argon","t":"Га? Хіба це не добре?"},{"a":"king","t":"Вітаю, простолюд! Схиліть голови перед моєю пишністю!"},{"a":"ashley","t":"А! Ваша Величносте! Ешлі для несення служби прибула!"},{"a":"king","t":"Прекрасний приклад вірного солдата! Продовжуй!"},{"a":"ashley","t":"Так точно! Дякую, сер!"},{"a":"tavern","t":"Вибачте, Рейнгольде, ваше вино ще не прибуло."},{"a":"king","t":"Отакої! Повернуся тоді завтра."},{"a":"argon","t":"І що це було?"},{"a":"ashley","t":"А! О! Якось я служила повелителю. Старі звички спрацювали."},{"a":"argon","t":"Круто! Поділися деталями!"},{"a":"ashley","t":"Ні."}]},{"id":"ashley_05","i":6,"title":"Поворотна Оповідь","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"...І ось, значить, кажу я..."},{"a":"ashley","t":"«Озброєна і готова? Ну, в якомусь сенсі готова!»"},{"a":"argon","t":"Ха-ха-ха!"},{"a":"argon","t":"Ешлі, будь ласка, розкажи ще про того повелителя...."},{"a":"ashley","t":"От халепа! Ти ж так просто не відчепишся?.. Добре."},{"a":"ashley","t":"У самураїв є повелитель. Даймьо. Ми служимо йому та захищаємо ціною свого життя."},{"a":"argon","t":"Дуже почесно!"},{"a":"ashley","t":"Так ось, одного разу під час обіду..."},{"a":"ashley","t":"І тут раптово бац! Ніндзя. По всій кімнаті. І усі... по душу мого повелителя."},{"a":"ashley","t":"Ми билися. Не в перший раз таке трапилося. Але..."},{"a":"ashley","t":"Удача відвернулася. Я втратила руку."},{"a":"ashley","t":"І потім... втекла. Залишила його помирати."},{"a":"argon","t":"Ешлі..."},{"a":"ashley","t":"Рррагх! Треба було померти там!"},{"a":"ashley","t":"Найю, налий-но ще!"},{"a":"tavern","t":"Ешлі, тобі вже досить на сьогодні."},{"a":"ashley","t":"Добре. Добре. З мене досить."},{"a":"ashley","t":"Хай так. Аргону, піди до Лілу і повідом, що я збираюся в небезпечну пригоду."},{"a":"argon","t":"Га? Зараз?!"},{"a":"ashley","t":"Ага. Я прямую... в печери Аврори. Треба поквапитися!"}]},{"id":"ashley_06","i":7,"title":"Око за Я","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"Дівчинка-ніндзя... Підслуховуєш, значить?"},{"a":"yami","t":"Трохи... Вийдемо?"},{"a":"ashley","t":"Ха! Нема настрою для бійки."},{"a":"yami","t":"То мій клан зробив це з повелителем Кусунокі. Мене давно відправили у вигнання... але можливо... ви приймете мої вибачення."},{"a":"ashley","t":"Дякую, але не треба. Провина не твоя. Моя."},{"a":"yami","t":"Розумію... Можливо навіть краще, ніж можна уявити."},{"a":"yami","t":"Проте тобі є заради чого і кого жити далі."},{"a":"yami","t":"У тебе є друзі. Улюблене місто. Тваринки."},{"a":"yami","t":"Однак якщо тобі і цього мало, можу викликати тебе на дуель."},{"a":"ashley","t":"Ого, безкоштовне вбивство від ніндзя? Ти мене балуєш."},{"a":"ashley","t":"Дякую, але відмовлюся. Хоча... може пізніше."},{"a":"yami","t":"Як хочеш."}]},{"id":"ashley_07","i":8,"title":"Один останній бій","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Пф-ф... Пф-ф... Ешлі тут нема."},{"a":"lilu","t":"Вона знову десь загубилася?.."},{"a":"lilu","t":"Так... стоп. Мені закрутили голову?"},{"a":"ashley","t":"Я ж начебто до вулкану Попелястого озера йшла..."},{"a":"ashley","t":"Неважливо."},{"a":"ashley","t":"Тааак! Прокидайтеся, кретини! Ешлі прийшла!"},{"a":"monster_Grotto_Mob","t":"Людина.. пʼяна?"},{"a":"ashley","t":"Сьогодні обійдемося без лікаря: лише я і жага смерті! Буду битися до останнього подиху!"},{"a":"ashley","t":"Мені все одно! Так, хто перший?"},{"a":"monster_Ruins_Mob","t":"Аргх! Давайте!"},{"a":"ashley","t":"Оце так!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"priest","t":"О, милостива богиня... це ж?.."},{"a":"priest","t":"Матінко! Яка кривава бійня!"},{"a":"monster_Grotto_Mob","t":"Хе-хе-хе."},{"a":"priest","t":"Вибачайте, чудовиська. Я лише заберу свого компаньйона."},{"a":"monster_Grotto_Mob","t":"Нізащо! НІЗАЩО! Диви, що вона наробила! Самурайка мертва. Мертвіше нікуди."},{"a":"priest","t":"Та дихає вона. Нашу Ешлі так легко не візьмеш."},{"a":"monster_Ruins_Mob","t":"Що? Ну то зараз закінчу почате!"},{"a":"priest","t":"Нічого ти тут не кінчатимеш."},{"a":"monster_Grotto_Mob","t":"Хе-хе-хе! А що ти ЗРОБИШ? Зцілиш нас?"},{"a":"priest","t":"Ви не залишили мені вибору. Хай пробачить вас богиня Астея..."},{"a":"priest","t":"Бо я не пробачу..."}]},{"id":"ashley_09","i":10,"title":"Постільний гніт","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"...Ух."},{"a":"priest","t":"А ось і ти."},{"a":"ashley","t":"Га? Ось лихо... і ти також тут. Як? Як тобі вдалося?"},{"a":"priest","t":"Здається, ти подобаєшся богині. Вона відправила мені."},{"a":"ashley","t":"Лишенько... Гаразд вже, дай мені піти з миром."},{"a":"priest","t":"Якщо ти так просиш."},{"a":"ashley","t":"Ш-ш-ш. Нарешті."},{"a":"ashley","t":"..."},{"a":"ashley","t":"...Чому ти мене ЗЦІЛЮЄШ?"},{"a":"priest","t":"Твої слова розходяться з серцем."},{"a":"priest","t":"Магія лікування лише підсилює твоє бажання жити. Якби ти і правда хотіла померти, моя магія не впоралася б."},{"a":"ashley","t":"Ось як..."},{"a":"priest","t":"А тепер відпочинь трохи. Тобі багато про що подумати треба."}]},{"id":"ashley_10","i":11,"title":"Час думати","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Ти повернувся! Лілу тебе скрізь шукала!"},{"a":"argon","t":"...Ти теж виглядаєш трохи пошарпаним."},{"a":"ashley","t":"Не зважай, мене підлатали. Ще й прочухана отримав."},{"a":"argon","t":"Від Фрейї? Це важко уявити."},{"a":"ashley","t":"Ага. Вона сказала мені почати думати. От і думаю."},{"a":"tavern","t":"Думаєш? Це щось нове!"},{"a":"ashley","t":"Припини це!"},{"a":"ashley","t":"...ось що я хотів би сказати, але ти правий."},{"a":"ashley","t":"Застряг у минулому так довго, я забув думати взагалі."},{"a":"argon","t":"Думати про що?"},{"a":"ashley","t":"Хм. Купа всього."},{"a":"ashley","t":"Непомітно для мене, здається, я назбирав багато речей, які мені стали дорогі."},{"a":"ashley","t":"Місто. Люди. Крамар. І ти, хлопчику-лицарю."},{"a":"ashley","t":"Знадобилося лише кілька зіткнень зі смертю, щоб помітити. Мабуть, я тугодум, хех."},{"a":"argon","t":"Маю честь, пані Самурай!"},{"a":"ashley","t":"Все ще ронін тут. Не сподівайся, що це зміниться найближчим часом."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Епілог","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"ashley","t":"Агов, Лілу! Я збираюся на новий квест. Приєднаєшся?"},{"a":"lilu","t":"Хм! Ага! Щоб ти мене знову відправила кудись на край світу?"},{"a":"lilu","t":"Або знову натрапиш на чудовиськ, а мені потім прикривати твій зад?"},{"a":"ashley","t":"Ні, я розумна жінка тепер. Трохи стишу швидкість."},{"a":"lilu","t":"Гм-м... ну, як скажеш."},{"a":"lilu","t":"Почекай..."},{"a":"ashley","t":"Ха-ха-ха! Жартуууую."},{"a":"ashley","t":"Якщо ти мене прикриєш, то я з тобою!"},{"a":"lilu","t":"Чудово! Але пообіцяй дещо."},{"a":"lilu","t":"Якщо стане зовсім тяжко, ми відступимо. ТИ відступиш."},{"a":"ashley","t":"Обіцяю. Слово роніна, якщо воно ще чогось варто."},{"a":"ashley","t":"Нам є куди повертатися."}]}]},{"id":"lilu","name":"Лілу","chapters":[{"id":"lilu_01","i":1,"title":"Здібна учениця","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Що ж, Поллуксе. Як тобі моє нове закляття? Чудово, правда?"},{"a":"lilu","t":"Так, цього разу ми точно це зробимо!"},{"a":"herbalist","t":"Доброго ранку, Лілу. Ти тут за щотижневою партією живого коріння?"},{"a":"lilu","t":"Так! Дякую тобі, Марібель!"},{"a":"herbalist","t":"Ти багато замовила цього тижня! Що твій майстер робить із цим усім?"},{"a":"lilu","t":"Насправді, десь половина із цього для мене. У мене серйозні дослідження!"},{"a":"herbalist","t":"О! На яку тему?"},{"a":"lilu","t":"Закляття зцілення! Я весь минулий тиждень лікувала рани й синці в тренувальному залі!"},{"a":"herbalist","t":"Добре, героям пощастило, що ти поряд з ними."},{"a":"herbalist","t":"...Це стосується і Аргона!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"Мені треба бігти! Дякую!"}]},{"id":"lilu_02","i":2,"title":"Грім і блискавка","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Ось, майстре Грімаре. Нове живе коріння."},{"a":"wizard","t":"Дякую, Лоло. А ось нове домашнє завдання."},{"a":"lilu","t":"О! Магічний фоліант! Він про зцілення?"},{"a":"lilu","t":"«Посібник для негідників і лиходіїв»?"},{"a":"lilu","t":"Яка велика книга! Тут навіть є цілий розділ про прокляття!"},{"a":"wizard","t":"...Прокляття?"},{"a":"wizard","t":"Хм... прокляття?.."},{"a":"lilu","t":"Майстре?"},{"a":"wizard","t":"35 років тому, у цей самий день... я..."},{"a":"lilu","t":"Майстре Грімаре?!"},{"a":"wizard","t":"...Я забув. А ти хто?"},{"a":"lilu","t":"Я Лілу, ваша учениця. Можна Лола..."},{"a":"lilu","t":"Добре, неважливо. Я буду вивчати цю книгу. Дякую, Гріме."}]},{"id":"lilu_03","i":3,"title":"Помутніння розуму","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"...Додамо щіпку срібного пилу і... готово!"},{"a":"lilu","t":"Дивись, як сяє! Непогано, так, Поллуксе?"},{"a":"lilu","t":"Якщо «Посібник для негідників і лиходіїв» говорить правду, це зілля має..."},{"a":"wizard","t":"Лоло, що за гамір? Я тут намагаюся заснути!"},{"a":"lilu","t":"Майстре Грімаре! Завдяки вашій книзі я приготувала дуже складне зілля! Воно має..."},{"a":"wizard","t":"Що-що ти зробила?!"},{"a":"wizard","t":"Що ж, давай його сюди! Спробуємо!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Майстре Грімаре?"},{"a":"wizard","t":"Лілу! Я м-м-маю з-з-звільнитися! В-в-випусти мене з розуму цього д-д-дурня!"},{"a":"lilu","t":"М-майстре Грімаре! З вами все гаразд?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"Фу! Віддає фруктами!"},{"a":"wizard","t":"Непогано, Лоло. А тепер повертайся до своїх справ."},{"a":"lilu","t":"...Це було НЕ нормально."}]},{"id":"lilu_a","i":3,"title":"Віковий накопичувач","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"lilu","t":"Грімаре, а ти не казав, що у тебе є й інша <c1>книга колекціонера</c1>!"},{"a":"wizard","t":"<c1>Книга колекціонера</c1>...? Щось знайоме..."},{"a":"lilu","t":"Ого! Та тут купа інформації! <c1>Дамокл</c1>... <c1>Бурштинова цитадель</c1>..."},{"a":"lilu","t":"<c1>Велика паличка Грімара</c1>...? Це ти її так назвав?"},{"a":"lilu","t":"Так багато сторінок! А ти ще той колекціонер!"},{"a":"sundragon","t":"Були часи!"},{"a":"wizard","t":"Сондра... це ти, старина?"},{"a":"lilu","t":"Ого! Так ви знайомі?"},{"a":"sundragon","t":"Авжеж. Молодий Грімар був просто в захваті від свої книги колекціонера."},{"a":"sundragon","t":"Здається, завдяки їй він отримав престижний титул серед своїх людей-однодумців... «Ботан», чи як там?"},{"a":"lilu","t":"Ой..."},{"a":"sundragon","t":"Ми зустрічалися, коли він шукав рідкісні предмети, і разом створили <c1>казан синтезу</c1>."},{"a":"sundragon","t":"Він днями і ночами синтезував сотні предметів... навіть під час повного місяця!"},{"a":"lilu","t":"Стільки зусиль докладено... Але його колекція все ще неповна!"},{"a":"lilu","t":"Присягаю, я вас вилікую, майстре Грімаре! Ви маєте завершити працю свого життя!"},{"a":"sundragon","t":"Час жорстокий до людства. Бажаю тобі успіхів у квестах, крихітко."}]},{"id":"lilu_04","i":4,"title":"Кінець родоводу","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"З майстром Грімаром щось не так..."},{"a":"lilu","t":"Його голос, ніби хтось говорив зсередини нього!"},{"a":"lilu","t":"Можливо, це якесь закляття перетворення?"},{"a":"lilu","t":"Або навіть..."},{"a":"leather","t":"Слухай, Лілу! Щось пішло не так на королівському бенкеті!"},{"a":"lilu","t":"Тамас? Що трапилося?"},{"a":"leather","t":"Щось пов'язане із загарбником у замку. Трохи боязно!"},{"a":"lilu","t":"Загарбник!.. О ні, це ж перший день Аргона в якості лицаря!"},{"a":"lilu","t":"Дякую, Тамасе. Мені треба бігти!"},{"a":"lilu","t":"О ні...! Що тут відбувається?!"},{"a":"lilu","t":"Аргоне, де ти?!"},{"a":"king","t":"А-а-а..."},{"a":"lilu","t":"КОРОЛЬ РЕЙНГОЛЬД?! З вами все гаразд?!"},{"a":"king","t":"Ох, моє безцінне життя... щезає..."},{"a":"lilu","t":"Погані справи!.."},{"a":"lilu","t":"Сконцентруйся, Лілу! Згадай навчання мудреця!"},{"a":"lilu","t":"Королю Рейнгольде! Не рухайтеся! <c1>Зцілення</c1>!"},{"a":"king","t":"Не діє... Прошу... збережи моє прекрасне тіло..."},{"a":"lilu","t":"Не діє..."},{"a":"lilu","t":"О ні... можливо, це... отрута?"},{"a":"lilu","t":"...Як і мої батьки!.. Цього разу в мене вийде! Має вийти!"},{"a":"lilu","t":"<c1>Велике очищення від отрути!</c1>"},{"a":"king","t":"...А-а-а... Що?"},{"a":"lilu","t":"Королю Рейнгольде! Як почуваєтеся?"},{"a":"lilu","t":"Стривайте... Цей кубок захистив вас від сюрікена! Ви взагалі не постраждали!"},{"a":"king","t":"О! Насправді? Думаю, я трохи погарячкував."},{"a":"king","t":"Врешті-решт, смерть монарха — драматична подія."},{"a":"lilu","t":"Ох, Рейнгольде!"}]},{"id":"lilu_05","i":5,"title":"Обери свою отруту","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Ого, це було небезпечно... нібито."},{"a":"lilu","t":"Якщо б Рейнгольда насправді отруїли... Не думаю, що я б його врятувала."},{"a":"lilu","t":"Треба спрямувати зусилля на інше. Щоб ніхто не зазнав утрат, як я..."},{"a":"lilu","t":"Пані Сіє!"},{"a":"sia","t":"А, наша зірка! Лицаря відправили розібратися з незваним гостем. Можеш заспокоїтися."},{"a":"lilu","t":"(Лицаря? Нехай щастить, Аргоне!)"},{"a":"sia","t":"Дякую за... спасіння нашого короля, незважаючи на обставини."},{"a":"lilu","t":"Та нічого! Але якщо таке трапиться знову, я не впевнена, що зможу допомогти..."},{"a":"lilu","t":"Пані Сіє, ви щось знаєте про отрути?"},{"a":"sia","t":"Звичайно. Аконіт, також відомий як вовча отрута, дуже ефективно вбиває."},{"a":"sia","t":"Але мій особистий фаворит — рицин. Безшумний, смертельний і завжди в наявності..."},{"a":"lilu","t":"Емм... А як від нього рятувати?"},{"a":"sia","t":"О, я навіть не думала про це."},{"a":"lilu","t":"...Забудьте про моє запитання."}]},{"id":"lilu_06","i":6,"title":"Учитель та ученик","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Я повернулася, майстре Грімаре!"},{"a":"wizard","t":"О, з поверненням, Лоло."},{"a":"lilu","t":"Це неймовірно! Короля майже вбили!"},{"a":"wizard","t":"Ось як..."},{"a":"lilu","t":"Убивця з'явився нізвідкіля та кинув у нього сюрікеном!"},{"a":"lilu","t":"А потім я рушила йому на допомогу, коли він умирав на підлозі!.."},{"a":"wizard","t":"Е-е... Ще раз, хто ти?"},{"a":"lilu","t":"Так, ваш стан... Треба до нього повернутися!"},{"a":"lilu","t":"Можливо, це також отрута..."},{"a":"lilu","t":"Подивимося... Грімар дуже старий..."},{"a":"lilu","t":"Як уважаєш, Поллуксе?"},{"a":"lilu","t":"Так, треба порозпитувати в місті!"},{"a":"lilu","t":"Можливо, хтось зі старих мешканців пам'ятає молодого Грімара..."}]},{"id":"lilu_07","i":7,"title":"Знання предків","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Майстре Теодоре!"},{"a":"master","t":"Та це ж Лілу! Потрібна моя допомога?"},{"a":"lilu","t":"Я хотіла запитати, чи не могли б ви мені розповісти про Грімара в юності?"},{"a":"lilu","t":"...Ви ж такий... старий... і таке інше."},{"a":"master","t":"Хо-хо-хо! Авжеж, авжеж."},{"a":"master","t":"Старий Грімар завжди був трохи... дивакуватий."},{"a":"master","t":"Але тоді, коли я був ще малим, він був набагато кмітливішим. Навіть у шахах мені не поступався."},{"a":"master","t":"А після тієї подорожі до руїн Хроноса... Якщо подумати, він завжди був не від світу цього."},{"a":"lilu","t":"Руїни Хроноса! Це ж таке небезпечне місце!"},{"a":"lilu","t":"...Уся цивілізація перетворилася на руїни в пошуках магії часу... "},{"a":"lilu","t":"У тому місці повно магічних аномалій! Що ж отримав Грімар, коли його відвідав?"},{"a":"lilu","t":"Ти правий, Поллуксе, це наш єдиний ключ до розгадки. Треба все розвідати!"},{"a":"lilu","t":"Але нам знадобиться супровід... Попросимо Аргона?"},{"a":"lilu","t":"Ні! А що, якщо петля часу раптово перетворить його на старика? Або як Грімар..."},{"a":"lilu","t":"...Мені на думку спадає лише одна особа, яка нам може допомогти..."},{"a":"lilu","t":"Це буде не так просто, Поллуксе! Але ми маємо спробувати!"},{"a":"lilu","t":"Дякую, Теодоре! Ви мені дуже допомогли!"},{"a":"master","t":"Немає за що, Лілу! Побачимося!"},{"a":"master","t":"..."},{"a":"master","t":"...Яка розумна сова!.."}]},{"id":"lilu_08","i":8,"title":"Спільна справа","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Пане Рудо, прошу! Не йдіть, мені треба поговорити з вами!"},{"a":"rudo","t":"Геть, дівча, я не бажаю це слухати."},{"a":"rudo","t":"Пограй зі своєю совою десь в іншому місці!"},{"a":"lilu","t":"Я знаю, що ви не любите заклинателів... Але мені дійсно потрібна ваша допомога!"},{"a":"lilu","t":"Мені треба вирушити в руїни Хроноса, але я не можу йти одна! "},{"a":"rudo","t":"Чому б тобі не попросити того хлопчака Аргона, твого лицаря в сяючих латах?"},{"a":"lilu","t":"Він... зараз зайнятий іншими справами..."},{"a":"lilu","t":"Тобто немає сенсу вас просити..."},{"a":"rudo","t":"Ти правильно зрозуміла, дівча."},{"a":"tavern","t":"Так прикро, люба."},{"a":"tavern","t":"Я чула, що повелителя циклопів з руїн Хроноса ніколи не долали в поєдинку..."},{"a":"tavern","t":"Для супроводу Лілу через ці руїни потрібен виключний воїн!"},{"a":"rudo","t":"...Кажеш, ніколи не долали?"},{"a":"rudo","t":"Чудово, я згоден. Скільки руйнувань потрібно зробити?"},{"a":"lilu","t":"Упевнена, що багато!"},{"a":"lilu","t":"Справа в тому, що мені потрібно знайти джерело потоку часу в різних кристалах та ізолювати..."},{"a":"rudo","t":"Давай коротше."},{"a":"lilu","t":"...Руйнувати треба монстрів і магічні кристали."},{"a":"rudo","t":"Згода. Будеш мені винна."},{"a":"lilu","t":"Чудово! Дуже дякую, пане Рудо!"},{"a":"rudo","t":"Подякуєш після нашої подорожі. Це не прогулянка парком."},{"a":"lilu","t":"Я буду зцілювати ваші рани, якщо зустрінеться забагато монстрів!"},{"a":"rudo","t":"Хм. Не думаю."},{"a":"lilu","t":"І тобі спасибі, Найя!"},{"a":"tavern","t":"Не проблема, люба."}]},{"id":"lilu_09","i":9,"title":"Дзеркальний світ","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Я візьму циклопів на себе! Ідіть далі!"},{"a":"rudo","t":"Давайте, жирні циклопи! Я приніс вам вівса!"},{"a":"lilu","t":"Ясно! Щасти тобі!"},{"a":"lilu","t":"Ось вона... Зала часу. І згідно з моїми дослідженнями..."},{"a":"lilu","t":"...Цей басейн має бути пов'язаний із фрагментованою часовою лінією!"},{"a":"lilu","t":"Паралельним усесвітом, у якому місто Хронос ще й досі процвітає..."},{"a":"lilu","t":"Поглянь, Поллуксе! Якщо дивитися у воду... можна дещо побачити!"},{"a":"lilu","t":"Ніби люди Хроноса живуть нормальним життям десь там..."},{"a":"lilu","t":"Ой... тобі не здається, що цей чоловік махає нам рукою?"},{"a":"lilu","t":"Він дуже схожий на... Невже це Грімар?!"}]},{"id":"lilu_10a","i":10,"title":"Вічне прокляття","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Грімаре!!! Пий!"},{"a":"wizard","t":"Га? Це щось... мені нагадує."},{"a":"lilu","t":"Це особлива настойка на воді з Хроноса..."},{"a":"wizard","t":"...Стабілізована й двічі очищена нитками долі?.."},{"a":"lilu","t":"...і матеріалізована за допомогою дистильованої ектоплазми."},{"a":"wizard","t":"А ще присмачена щіпкою порошку з глибоководного коралу!"},{"a":"wizard","t":"Вражаюча робота, Лілу. Майстер дуже тобою пишається."},{"a":"lilu","t":"Г-грімаре... Ти прийшов до тями! Спрацювало!"},{"a":"wizard","t":"Які дивні відчуття... Ніби туман щойно вивітрився з моєї голови..."},{"a":"lilu","t":"Я погано уявляю, як діє це зілля, але... тут сталася якась нісенітниця."},{"a":"lilu","t":"Ми бачили твоє відбиття в басейні! У фрагментованій часовій лінії!"},{"a":"wizard","t":"Хо-хо! Та невже? У мене є одна гіпотеза..."},{"a":"wizard","t":"Поллуксе, любий. Ти не міг би привести старого Оуена? Мені здається, тут доведеться багато чого пояснювати..."}]},{"id":"lilu_10b","i":11,"title":"Теорема про розподіл часу","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"elderowen","t":"Оце так, друже мій! Твоя розповідь мене вразила!"},{"a":"lilu","t":"Мені й самому важко повірити... Невже Грімар вижив після тих страшних подій у Хроносі?"},{"a":"wizard","t":"Коли стався збій у заклятті часу, усе місто перейшло в іншу часову лінію."},{"a":"elderowen","t":"Той день дуже добре закарбувався в моїй пам'яті. Ціле місто вмить зникло!"},{"a":"elderowen","t":"Ми знайшли лише самотню дитину, яка блукала руїнами..."},{"a":"lilu","t":"То був Грімар? Важко уявити вас обох дітьми..."},{"a":"elderowen","t":"Хо-хо! Ми швидко подружилися, чи не так?"},{"a":"wizard","t":"Звісно. Я вчився на чарівника, щоб самому подивитися на цю дивну подію."},{"a":"wizard","t":"Якщо Лілу нічого не здалося, то не виключено, що існує ще один Грімар."},{"a":"lilu","t":"Інший Грімар, якого ми бачили... Тобто ти існуєш і на іншій часовій лінії?!"},{"a":"wizard","t":"Схоже, що так. Спочатку ніяких наслідків не було, але..."},{"a":"wizard","t":"Коли обидва Грімари виросли, наші життєві шляхи й особистості почали розходитися."},{"a":"lilu","t":"І все більший магічний парадокс почав обтяжувати твій розум..."},{"a":"lilu","t":"Я зрозуміла! Випите зілля з руїн Хроноса має повернути тебе до іншої часової лінії!"},{"a":"wizard","t":"Це моя теорія. Я впевнений, що інший Грімар теж її оцінить."},{"a":"lilu","t":"Господи... Усе це дуже важко переварити. Може, до ранку в голові трохи проясниться... Ти йдеш, Поллуксе?"},{"a":"elderowen","t":"Що стосується нас, друже Гріме, я вважаю, нам ще багато чого згаяного надолужувати!"},{"a":"wizard","t":"Говори за себе, старий телепню! Я відчуваю себе молодим, як ніколи!"}]},{"id":"lilu_epilogue","i":12,"title":"Епілог","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Привіт, Грімаре! Ось новий рецепт. Він має діяти трохи довше!"},{"a":"wizard","t":"Він значно кращий! Твої батьки пишалися б."},{"a":"lilu","t":"...Якби ж я вчила алхімію раніше..."},{"a":"wizard","t":"Я відчуваю те саме. Якби я повністю контролював себе, можливо..."},{"a":"lilu","t":"...Усе добре. Я вирішила зосередитися на майбутньому. Щоб стати кращою і врятувати інших від цієї долі."},{"a":"lilu","t":"...Упевнена, що мої батьки хотіли б цього."},{"a":"wizard","t":"Ти так подорослішала... Я тебе ледь упізнаю."},{"a":"wizard","t":"Власне... ти хто взагалі?"},{"a":"lilu","t":"О ні! Дія вже минає! Краще мені..."},{"a":"wizard","t":"Хо-хо-хо! Та я просто жартую. У мене гарне передчуття."},{"a":"wizard","t":"Тепер, поки в мене ясна голова... може, продовжимо вивчати магію?"},{"a":"wizard","t":"Майстер ще має чим здивувати!"},{"a":"lilu","t":"О! Може, розкажеш про поліморфізм? Чекаю з нетерпінням!"}]}]},{"id":"polonia","name":"Полонія","chapters":[{"id":"polonia_01","i":1,"title":"Прославлений сухопутник","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Сухопутники!"},{"a":"polonia","t":"Чи-то мріяли ви колись про розповіді про безрозсудні піратські пригоди на морських просторах?"},{"a":"polonia","t":"Я, капітан Полонія Дель Монте, рекрутую банду для своєї посудини!"},{"a":"polonia","t":"Як онука славетного пірата Баросса Дель Монте я обіцяю вам здобич і пригоди!"},{"a":"argon","t":"Капітан Полонія, так?"},{"a":"polonia","t":"Еге ж. Цікаво? Такий жеребець, як ти, завжди стане в нагоді."},{"a":"argon","t":"Ж-жеребець?!"},{"a":"argon","t":"Ти помиляєшся! Я Аргон, майбутній лицар!"},{"a":"argon","t":"Піратство є незаконним, тому... прошу, здавайся та йди з миром!"},{"a":"polonia","t":"Якір мені в зябра! Бісовий лицар..."},{"a":"polonia","t":"Тут така справа, я законний пірат, як-от... той сухопутник Робін Гуд."},{"a":"polonia","t":"...Я краду в багатих і віддаю бідним!"},{"a":"argon","t":"О! Це начебто шляхетно. Немає питань, так тримати!"},{"a":"polonia","t":"...Фух."},{"a":"tavern","t":"Теж сьогодні не пощастило, а?"},{"a":"polonia","t":"Арр, непросто жити на морських просторах."}]},{"id":"polonia_02","i":2,"title":"Історія Дель Монте","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"tavern","t":"Сьогодні більше не наймаєш, Полоніє?"},{"a":"polonia","t":"Немає сенсу. Я невдалий піратський капітан, лише маю ім'я Дель Монте..."},{"a":"tavern","t":"Той Баросс Дель Монте... він твій дід?"},{"a":"polonia","t":"Еге ж! Славетний і легендарний! Нинішні часи непрості для нас, піратів..."},{"a":"polonia","t":"Нині всі торгові кораблі мають магічні штуки, які з легкістю виявляють таких морських вовків, як я."},{"a":"polonia","t":"Але Баросс був не таким! Магія чи ні, але він атакував зненацька, з туману!"},{"a":"polonia","t":"Забирав усе, до останньої сорочки, залишаючи лише свій громоподібний сміх, як візитівку..."},{"a":"polonia","t":"Навіть коли всі пірати вже припинили діяльність, він продовжував тероризувати моря десятиліттями!"},{"a":"tavern","t":"Непоганий приклад!"},{"a":"polonia","t":"Еге ж! А після кожної подорожі він завжди знаходив час відвідати свою онуку та повідати нову історію про свої авантюри..."},{"a":"polonia","t":"«Підняти чорний прапор! Вогонь з гармат! Команді відійти на кермо, приготуватися до пограбування!»"},{"a":"tavern","t":"На кермо? Чи може на корму?"},{"a":"polonia","t":"...Еех! До дідька! Я проста сухопутниця в маскарадному костюмі. Мені так складно розмовляти по-піратські."},{"a":"polonia","t":"Та що це за пірат, у якого немає корабля?!"},{"a":"tavern","t":"Немає корабля? Можливо, із цього й треба розпочати?"},{"a":"polonia","t":"Га?"},{"a":"tavern","t":"Капітан без корабля навряд чи зможе рекрутувати команду!"},{"a":"tavern","t":"Але якщо тобі потрібен корабель, я знаю, хто може допомогти."},{"a":"polonia","t":"...Насправді?"},{"a":"polonia","t":"Тобто присягаюся Веселим Роджером, ти мене виручила, тавернянко! За капітаном Полонією не заіржавіє!"},{"a":"tavern","t":"О, саме на це я і розраховую."}]},{"id":"polonia_03","i":3,"title":"Справний корабельник","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"carpenter","t":"Ти хочеш, щоб я побудував цілий корабель?"},{"a":"polonia","t":"Еге ж. Упораєшся?"},{"a":"carpenter","t":"Ще б пак! Це буде мій шедевр! Дай подивитися на план."},{"a":"carpenter","t":"Гм... Тут якось усе заплутано. Що це за карлючки?"},{"a":"polonia","t":"Я писала. Я не можу читати."},{"a":"carpenter","t":"Ага, це дещо пояснює. Проте цього буде достатньо."},{"a":"polonia","t":"Йо-хо-хо! Це буде найвеличніший корабель, який бачили моря після Баросса та «Бонавентури»!"},{"a":"carpenter","t":"Але виникає питання фінансів. Ти точно потягнеш?"},{"a":"polonia","t":"Еге ж, дублони — не питання. Зроби корабель, а я принесу здобич."}]},{"id":"polonia_a","i":3,"title":"Ногу на відсіч","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"polonia","t":"Привіт, кралечко. Ти цілителька?"},{"a":"priest","t":"Так, я Фрейя, жриця цього хра..."},{"a":"polonia","t":"Відрубай мені ногу."},{"a":"priest","t":"Прошу?"},{"a":"polonia","t":"Відрубай мені ногу!"},{"a":"priest","t":"Богине милостива, ні! Навіщо таке робити?"},{"a":"polonia","t":"Я ж піратка! Де ти бачила капітана піратів на двох ногах?!"},{"a":"polonia","t":"Відрубай мені ногу, а потім зліпи її докупи за допомогою магії!"},{"a":"priest","t":"Я категорично відмовляюся. Я поклялася Богині ніколи не шкодити людям."},{"a":"polonia","t":"Ой, жодної користі з вас, сухопутних! Гаразд! Але дублонів від мене не чекай!"},{"a":"priest","t":"...Дивачка якась."}]},{"id":"polonia_04","i":4,"title":"Доля капітана","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Арр, у цих єті купа здобичі! Я швидко розрахуюся за корабель!"},{"a":"leather","t":"Добре, друже, от і я. Що треба робити?"},{"a":"polonia","t":"Для тебе я капітан Полонія, салаго!"},{"a":"leather","t":"Звичайно, капітане друже. Що мені треба робити?"},{"a":"polonia","t":"Ти притягнув свій візок. Будеш тягати здобич, поки я грабуватиму цих єті."},{"a":"leather","t":"Ого, капітане друже, ти обкрадаєш цих прекрасних пухнастих створінь?"},{"a":"polonia","t":"Еге ж. Чомусь у них забагато цінностей, типу бойові молоти та складені луки."},{"a":"leather","t":"А як щодо шкір, капітане друже? Можна мені їх забрати?"},{"a":"polonia","t":"Не забувай, хто ти, салаго! Пірати грабують, а не вбивають!"},{"a":"leather","t":"Ох, шкода."},{"a":"polonia","t":"Як би не так! Якщо залишити жертвам життя, вони назбирають ще здобичі, яку можна потім забрати. Основи економіки!"},{"a":"polonia","t":"Не зупиняйся, салаго, якщо хочеш свою долю."},{"a":"leather","t":"Слухаюсь, капітане друже!"}]},{"id":"polonia_05","i":5,"title":"Перший рейс","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"carpenter","t":"Поглянь на шедевр усього мого життя!"},{"a":"polonia","t":"Він... він красивий. Аж сльоза покотилася з ока старого морського вовка."},{"a":"carpenter","t":"Правда? Мені довелося дещо змінити, а саме — я прибрав гармати з воронячого гнізда. Не розумію, навіщо вони тобі..."},{"a":"carpenter","t":"Але вийшло дуже добре, чи не так?"},{"a":"polonia","t":"Саме так, чоловіче. Ось тобі дублон, ти заробив."},{"a":"carpenter","t":"Звичайно ж! Ще одна річ. Хоча я і вмілий столяр, я зовсім не тямлю в тканинах."},{"a":"carpenter","t":"...А без вітрил твій корабель ніколи не залишить порт!"},{"a":"polonia","t":"Твій шедевр і так подобається капітану, чоловіче. Вітрила у мене є."},{"a":"carpenter","t":"Ого! Та це ж витвір мистецтва! Ще й магічний. Де ти це знайшла?"},{"a":"polonia","t":"Успадкувала від дідуся Баросса. Ті самі вітрила, що були на його кораблі — «Бонавентурі»!"},{"a":"carpenter","t":"Зрозуміло! Гідне завершення цього шедевра!"},{"a":"carpenter","t":"Що ж, капітане Полоніє, «Неймовірний Аллан» твій!"},{"a":"polonia","t":"Ти назвав його «Неймовірний Аллан»? Стривай..."},{"a":"polonia","t":"Ця фігура на носу корабля... це ж ти! Голий?!"},{"a":"carpenter","t":"Ха-ха! Думаю, це найкраща фігура на носу, яку можна уявити для такого ідеального корабля!"}]},{"id":"polonia_b","i":5,"title":"Ноги в руки!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"polonia","t":"Моє вітаннячко."},{"a":"wood","t":"Що треба?"},{"a":"polonia","t":"Відрубай мені ногу."},{"a":"wood","t":"Зараз."},{"a":"polonia","t":"Я кажу... зачекай, ти не проти?"},{"a":"wood","t":"Чому б це? Постав ногу ось так. Думаю, ця сокира згодиться."},{"a":"polonia","t":"Е, зачекай!"},{"a":"wood","t":"Гарно не буде, але ти ж крута дівка, правда?"},{"a":"wood","t":"Треба лише знайти добрий джгут. Не хочу, щоб ти стекла кров'ю просто тут."},{"a":"polonia","t":"Спусти вітрила! Не так швидко!"},{"a":"polonia","t":"Я... я поспішаю на корабель! В... він скоро відпливає! До зустрічі!"},{"a":"wood","t":"...Ха! Люди. З ними ніколи не занудьгуєш."}]},{"id":"polonia_06","i":6,"title":"Спадщина на морі","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Мій королю, я принесла жахливі новини."},{"a":"king","t":"О ні! У Загубленому золотому місті скінчилося золото?!"},{"a":"sia","t":"На щастя, не такі жахливі."},{"a":"sia","t":"Проте один докучливий пірат грабує ваш особистий торговий флот."},{"a":"sia","t":"...Збитки оцінюються в понад 100 трильйонів золотом."},{"a":"king","t":"Хай допоможе нам Богиня! Але ж хіба мій флот не оснащено найсучаснішою системою магічного виявлення піратів?"},{"a":"sia","t":"Схоже, від неї мало користі. Як і сам великий Барос, цей корабель уникає навіть найкращої нашої магії..."},{"a":"sia","t":"...І тікає з нашим золотом у відкрите море."},{"a":"king","t":"Нечуване варварство! А що з командою?"},{"a":"sia","t":"Їх щадять, мій королю. Якщо вони не чинять опору."},{"a":"king","t":"Тоді золото — це невелика ціна. Я харчуватимуся селянською їжею, доки не поверну свої статки!"},{"a":"king","t":"...Скільки часу знадобиться?"},{"a":"sia","t":"Приблизно 2 дні, мій королю."},{"a":"king","t":"Які важкі часи настали..."}]},{"id":"polonia_07","i":7,"title":"Відпустка на суші","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Капітан Полонія зійшла на берег! Я всіх пригощаю!"},{"a":"tavern","t":"Полоніє! Чи мені називати тебе... капітан Полонія? Як там, «справи» йдуть добре?"},{"a":"polonia","t":"Можеш заприсягнутися своїм сухопутним днищем, що так воно і є! У цих морях удосталь усього, чим можна поживитися!"},{"a":"polonia","t":"Куди б я не спрямувала свій корабель, вітрила мого дідуся добряче ловлять вітер. Таке рідко побачиш!"},{"a":"tavern","t":"Упевнена, Барос би тобою пишався. І що ти зробила із цим... нечесно отриманим добром?"},{"a":"polonia","t":"Те, що й інші пірати. Ми з командою закопали трохи тут, трохи там..."},{"a":"tavern","t":"О-о-о! Карти скарбів! Як цікаво!"},{"a":"polonia","t":"Ми, пірати, такі. Щось ховаємо на холодні зимові місяці, як ті сухопутні білки."},{"a":"tavern","t":"А решту?"},{"a":"polonia","t":"Віддала одній милій жіночці з храму."},{"a":"tavern","t":"Пожертви сиротам? Я й не знала, що пірати займаються доброчинністю."},{"a":"polonia","t":"Добро... що?"},{"a":"tavern","t":"Не має значення. Так що замовите, капітане?"},{"a":"polonia","t":"Як завжди — напій морського вовка! Собі й усім присутнім тут сухопутним, які не бояться випасти в осад..."},{"a":"polonia","t":"Наступне замовлення за мій рахунок! Баросcи повертаються в море! Йо-хо-хо!"}]},{"id":"polonia_08","i":8,"title":"Шепіт з минулого","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Русал, готовий до наступного запливу?"},{"a":"baker","t":"Завжди готовий, капітане! Хоча, треба сказати, що..."},{"a":"baker","t":"Хоч мені і подобається допомагати досліджувати дно морське, піратство мене не приваблює!"},{"a":"polonia","t":"Друже, простіше будь. У нас важлива місія. Твій капітан розширює горизонти."},{"a":"polonia","t":"Сьогодні без піратства. Але якщо пощастить, ми знайдемо затонулий корабель і поживемося чим-небудь! Хо-хо-хо!"},{"a":"baker","t":"Капітане? А що це там по курсу?"},{"a":"polonia","t":"Арр! Спокій, рибко! Це напевно та сама «Бонавентура»! Корабель мого дідуся."},{"a":"baker","t":"Точно? Якийсь він побитий життям..."},{"a":"polonia","t":"...Забери мене Нептун! Та сама «Бонавентура»! Але... це неможливо! Дідусь вже давно помер!"},{"a":"polonia","t":"Друзі! Зміна курсу! НАМ ПОТРІБЕН ЦЕЙ КОРАБЕЛЬ!"}]},{"id":"polonia_09","i":9,"title":"Легенда на плаву","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"baker","t":"...Скажи мені хто, що я зійду на борт стародавньої руїни, ха!"},{"a":"polonia","t":"Дивись під ноги, матросе! Корабель майже згнив."},{"a":"baker","t":"Якщо вже чесно, то я б краще поплавав. А що ми взагалі забули на цій посудині?"},{"a":"polonia","t":"Як це «що?»? Це знаменита «Бонавентура» Баросса!"},{"a":"polonia","t":"Треба дізнатися, що тут сталося. Ця руїна взагалі не повинна бути на ходу."},{"a":"baker","t":"...Корабель-примара, не інакше."},{"a":"polonia","t":"Агов! Від мене не втечеш! Привидів не існує!"},{"a":"baker","t":"А як же Зо..."},{"a":"polonia","t":"Друже, стули пельку. Треба пошукати щось корисне."},{"a":"baker","t":"Цей бортовий журнал лякає..."},{"a":"polonia","t":"Ага, записи капітана!"},{"a":"baker","t":"Неначе в душу дивиться...так?"},{"a":"polonia","t":"Журнале, ти йдеш зі мною. Пошукайте ще що-небудь корисне."},{"a":"polonia","t":"...Друже, не чіпай моє волосся!"},{"a":"baker","t":"Капітане, я тут."},{"a":"polonia","t":"...ААААААА! Тікаймо з корабля!"}]},{"id":"polonia_10","i":10,"title":"Спадщина пірата","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Ваш капітан повернувся. Підняти вітрила, ми відчалюємо!"},{"a":"baker","t":"Капітане, дивиться! «Бонавентура» тоне!"},{"a":"polonia","t":"Ось холера! Як таке можливо? Після багатьох років? Невже журнал тримав її на плаву?"},{"a":"baker","t":"...Можливо, корабель виконав свою місію."},{"a":"polonia","t":"Бароссе, морський пес, звідки ж ти знав?"},{"a":"baker","t":"Полонія, що там з журналом?"},{"a":"polonia","t":"Так, точно. Дай-но подивлюся..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"...Русале, справа є до тебе."},{"a":"baker","t":"Ага, дай-но прочитаю."},{"a":"baker","t":"Гм-м... схоже на інструкції, як знайти щось під водою."},{"a":"polonia","t":"Затонулий храм? Це вже не новина."},{"a":"baker","t":"Ні, це зовсім інше місце... Може, Загублене золоте місто?"},{"a":"baker","t":"Загублене золоте місто не пішло під воду..."},{"a":"polonia","t":"Тобто...Тобто це не вигадка? Це місто дійсно існувало?"},{"a":"polonia","t":"Русале, йди поплавай. Це доля."},{"a":"polonia","t":"Якщо всі чутки виявляться правдивими, ви не пошкодуєте про подорож."}]},{"id":"polonia_11","i":11,"title":"Затонуле золоте місто","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"baker","t":"Фух! Ми на місці! Ти як там, капітане?"},{"a":"polonia","t":"*кашляє* *ах*"},{"a":"polonia","t":"Хех!.. ось це у тебе... швидкі ноги... для русала-то!"},{"a":"baker","t":"І це гарно! Цей вхід знаходиться так глибоко під водою, не думаю, що хоч хтось зміг би дістатися сюди."},{"a":"polonia","t":"Точно підмічено! Я ледь не потонула. Ноги моєї тут більше не буде."},{"a":"baker","t":"Хай захистить нас богиня!.. Полоніє, дивися!"},{"a":"polonia","t":"Отакої! Затонуле золоте місто..."},{"a":"polonia","t":"Це місце... Ніколи нічого подібного не бачила..."},{"a":"baker","t":"Тут гори багатств! Золото, перлини... Загублене золоте місто навіть і поруч не стояло!"},{"a":"polonia","t":"Усе своє життя мій дід шукав це місце."},{"a":"baker","t":"Зрештою, він нічого не зміг забрати з собою на сушу, тому залишив все це своїй улюбленій внучці."},{"a":"polonia","t":"*схлип* Очі наповнюються сльозами..."},{"a":"baker","t":"Дати тобі трохи часу, капітане?"},{"a":"polonia","t":"Жартуєш? Там є чим поживитися! І ти стаєш першим помічником капітана! Готовий поплавати?"},{"a":"baker","t":"Я потягну здобич і пірата? Треба розім'яти м'язи."}]},{"id":"polonia_epilogue","i":12,"title":"Епілог","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Гм-м..."},{"a":"baker","t":"Полоніє, у нас ще заплив намічається?"},{"a":"polonia","t":"Ні, друже. У мене велика проблема."},{"a":"polonia","t":"У мене забагато грошей! Вже і пляжів не залишилося, де це все закопувати."},{"a":"baker","t":"Ух, мене розбурхує належна мені частка."},{"a":"baker","t":"А, точно!"},{"a":"baker","t":"Я тут поплавав навколо затонулої «Бонавентури»..."},{"a":"baker","t":"Там мало що залишилося, але ось дещо. Щось впізнаєш?"},{"a":"polonia","t":"Старпом! Це ж наочник Баросса!"},{"a":"polonia","t":"Хо-хо-хо! Як я щаслива! Готова тебе затискати!"},{"a":"baker","t":"Радий служити, капітане! Упевнений, що таке було його бажання."},{"a":"polonia","t":"...Знаєш що, з мене вистачить цього підводного мародерства!"},{"a":"polonia","t":"Море — будинок пірата, а не золота жила! І неважливо, скільки там здобичі."},{"a":"polonia","t":"Як внучка великого Баросса, я дарую тобі Затонуле золоте місто і всі трофеї в ньому."},{"a":"polonia","t":"Дякую за допомогу, старпом. Якщо коли-небудь передумаєш щодо піратства, ласкаво просимо до нас."},{"a":"baker","t":"Дякую, капітане! Я пронесу в серце спогади про наші пригоди!"},{"a":"baker","t":"...Напевно, після повернення мені варто переговорити з Туту Мано."}]}]},{"id":"king","name":"Рейнгольд","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Король Рейнгольд..."},{"a":"king","t":"Ох... Здається, у мене з'явилися невідкладні справи!"},{"a":"sia","t":"Накопичилися, так би мовити. На мене чекають поважні особи."},{"a":"king","t":"Прощавай, крамарю! Я ще повернуся!"},{"a":"sia","t":"Ні, я так не думаю."}]},{"id":"king_01","i":1,"title":"Королівський суд","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"king","t":"Відкрився королівський суд! У кого є петиція — виходьте вперед!"},{"a":"rudo","t":"Гм."},{"a":"king","t":"Що королівство Рейнгольда може зробити для своїх підданих, великий... людиноведмедю?"},{"a":"rudo","t":"Я думаю, вам слід заборонити всю магію та вигнати заклинателів."},{"a":"king","t":"А-а-а... це... е-е-е..."},{"a":"king","t":"Ми... подумаємо над вашою пропозицією! Наступний!"},{"a":"herbs","t":"Приві-і-і-т! Я пропоную щодня влаштовувати СВЯТО ПІНЬЯТИ!"},{"a":"king","t":"Яка чудова ідея! Ми й справді могли б..."},{"a":"sia","t":"..."},{"a":"king","t":"...більше часу приділити обговоренню цього питання! Дякуємо за візит!"},{"a":"king","t":"...Сіє, скільки в нас на сьогодні ще петицій?"},{"a":"sia","t":"П'ятдесят п'ять, мій королю."},{"a":"king","t":"Ой, лишенько."}]},{"id":"king_02","i":2,"title":"Золоте серце й брак розуму","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"donovan","t":"Перепрошую, тут вільно?"},{"a":"sia","t":"Прийшов, щоб зіпсувати мені вихідний, Доноване?"},{"a":"donovan","t":"Навіщо ти так, Сіє? Я просто намагаюся налагодити стосунки з громадянкою Імперії."},{"a":"donovan","t":"Як там поживає наш недоумкуватий король?"},{"a":"sia","t":"Твої шпигунські прийомчики вже мохом поросли, Доноване. Рейнгольд не такий дурний, як ти вважаєш."},{"a":"sia","t":"Хоч із його обличчя не сходить дивна посмішка, проте він багато чим жертвує заради своїх підданих."},{"a":"sia","t":"Імператору... НАШОМУ імператору не завадило б цьому повчитися."},{"a":"sia","t":"Якби не я, він би геть виснажив себе, щоб покращити життя свого народу."},{"a":"donovan","t":"Правда? Це так зворушливо."},{"a":"sia","t":"Не заперечуватиму, що він дурник із золотим серцем. Але не варто його недооцінювати."}]},{"id":"king_03","i":3,"title":"Дозвілля короля","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"king","t":"Оце так! А ця купа звітів щось не меншає, правда?"},{"a":"sia","t":"Здається, знову доведеться над ними всю ніч сидіти."},{"a":"king","t":"Дякую, що допомагаєш мені, дорога Сіє!"},{"a":"sia","t":"Не варто подяки, мій королю. Так, тепер наступний звіт..."},{"a":"sia","t":"Фермери із Саутбурга недоплатили податків, посилаючись на поганий урожай."},{"a":"sia","t":"Здається, це вже вдруге..."},{"a":"king","t":"Надішлемо придворних чарівників для розслідування. Може, на їхні землі наслано якесь прокляття."},{"a":"sia","t":"Яке шляхетне рішення!"},{"a":"king","t":"І знову пробачимо їм борги. Саме так учинив би мій батько!"},{"a":"sia","t":"Дуже добре. Я теж уважаю, що король Кейнан зробив би так само."},{"a":"king","t":"Корона, яка дісталася мені в спадок від нього — нелегка ноша..."},{"a":"king","t":"Що там у наступному звіті?"},{"a":"sia","t":"Тут ідеться про напружене становище на кордоні із сусідньою імперією..."}]},{"id":"king_04","i":4,"title":"Стрибки в тіні","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Мій королю..."},{"a":"king","t":"Ой!"},{"a":"king","t":"П-прошу, повідомляйте про свою присутність, коли підкрадаєтеся ззаду!"},{"a":"sia","t":"Ох, той напад ніндзя вас дуже вразив, чи не так?"},{"a":"king","t":"Звичайно! Я був на волосину від смерті!"},{"a":"sia","t":"Мені посилити варту?"},{"a":"king","t":"У цьому... немає потреби. Але, будь ласка, надалі не підкрадайтеся так тихо!"},{"a":"sia","t":"Як скажете, мій королю."},{"a":"hemma","t":"Ох... Удома добре... Правда?"},{"a":"king","t":"А-А-А-А!!! Н-ніндзя?!"},{"a":"hemma","t":"Прийміть наші вибачення. Здається, ми помилилися."},{"a":"hemma","t":"Часом і Тіньова транслокація хибить."},{"a":"king","t":"П-прошу втриматися від ТІНЬОВОЇ ТЕЛЕПОРТАЦІЇ в моїй тронній залі!"},{"a":"sia","t":"К-королю Рейнгольде, з вами все гаразд?"},{"a":"king","t":"Так! Проведіть, будь ласка, цю... жахливу відвідувачку до виходу."},{"a":"sia","t":"Добре. Я подбаю про належний захист замку від таких вторгнень у майбутньому."},{"a":"hemma","t":"Цікавеньке місце ми знайшли. Ми ще повернемося."},{"a":"king","t":"Сподіваюся, що ні!"}]}]},{"id":"rudo","name":"Рудо","chapters":[{"id":"rudo_01","i":1,"title":"Людина-гора","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Бррр... Я погано вдягнений для такої холоднечі! Чому ми знову тут опинилися?"},{"a":"lilu","t":"Самоцвіти тут мають неймовірні властивості! Грімар сказав мені..."},{"a":"argon","t":"Стій, Лілу, Дивись! Там чоловік б'ється з єті!"},{"a":"lilu","t":"Чоловік?! Та він здоровий, наче гора!"},{"a":"lilu","t":"І він... долає єті?!"},{"a":"rudo","t":"Фух... Десятий."},{"a":"argon","t":"Уражаючий бій, сер! Ви були неперевершені!"},{"a":"rudo","t":"Га?"},{"a":"lilu","t":"Сер... ви поранені! Дайте я вас зцілю!"},{"a":"lilu","t":"<c1>Зці</c1>...!"},{"a":"rudo","t":"ВІДІЙДИ!"},{"a":"rudo","t":"Я в нормі. Воно само зцілиться."},{"a":"rudo","t":"Дітям не варто вештатися в таких місцях. Ідіть додому."},{"a":"argon","t":"Ого, цей чолов'яга не дуже довіряє магії."},{"a":"lilu","t":"Ні. Те, що я побачила в його очах... Це був страх."}]},{"id":"rudo_02","i":2,"title":"Сповіщення про виселення","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"elderowen","t":"На жаль, я не розумію..."},{"a":"rudo","t":"Та ти що! Тоді я скажу так, щоб твої старі вуха зрозуміли!"},{"a":"rudo","t":"Чарівник у цьому місті — буйний божевільний, тому його треба викинути геть заради безпеки всіх."},{"a":"elderowen","t":"Ой-йой... Які грубі слова..."},{"a":"rudo","t":"Ще вчора він попросив мене приглянути за Тимофієм..."},{"a":"rudo","t":"...Сказав, що цей Тим марить, нічого не розуміє та його треба тримати під наглядом."},{"a":"rudo","t":"Він і *Є* Тимофій!"},{"a":"elderowen","t":"Гм, так. Розумію."},{"a":"elderowen","t":"Незважаючи на його «стан», Тимофій Грімар є невід'ємною частиною цього міста."},{"a":"elderowen","t":"Він такий же корисний, як і безпечний. Не бачу причин хвилюватися."},{"a":"lilu","t":"Що за розмови про вигнання майстра Грімара?!"},{"a":"rudo","t":"Не втручайся, дівча."},{"a":"lilu","t":"Ні! Майстер Грімар — могутній чарівник, проте він нікому не зашкодить!"},{"a":"rudo","t":"Га! Чудово! Але якщо це місто підніметься на повітря, не кажіть-но, що я вас не попереджав."},{"a":"elderowen","t":"Який галасливий."},{"a":"lilu","t":"За ним треба приглядати..."}]},{"id":"rudo_03","i":3,"title":"Народжені з іскри","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"priest","t":"Вибачте... На що ви скаржитесь?"},{"a":"rudo","t":"Дідько. Чому в цьому місті так багато цих бісових заклинателів..."},{"a":"priest","t":"А, пан Рудо, наскільки я розумію."},{"a":"rudo","t":"Ми з тобою не друзі, чарівниця."},{"a":"priest","t":"Я жриця Богині. Мої сили не такі, як у чарівників."},{"a":"priest","t":"Я присягнула, що присвячу своє життя зціленню та захисту."},{"a":"rudo","t":"Я на це не поведуся. Ви, народжені з іскри, усі однакові."},{"a":"priest","t":"Ви знаєте про іскру?.."},{"a":"rudo","t":"Пф. Забудь-но, що я сказав. Я пішов."},{"a":"priest","t":"...Ти слухаєш, Лілу?"},{"a":"lilu","t":"Так, усе слухаю!"},{"a":"priest","t":"Ти пам'ятаєш мої уроки про іскру?"},{"a":"lilu","t":"Звичайно! Лише люди, народжені від іскри, можуть контролювати магічні закляття та керувати ними."},{"a":"lilu","t":"Проте цей феномен невідомий широкому загалу."},{"a":"priest","t":"Усе вірно! Цього я й очікувала від своєї найкмітливішої учениці!"},{"a":"priest","t":"Хоча виникає питання... Звідки він про це дізнався?.."},{"a":"lilu","t":"Гм... Ти думаєш?.."}]},{"id":"rudo_04","i":4,"title":"Бий і хапай","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Капітан Полонія отримує джекпот цього разу!"},{"a":"polonia","t":"Ціла королівська гробниця вже готова до добрячого пограбування!"},{"a":"rudo","t":"Тихіше, морячко. У мене справи."},{"a":"polonia","t":"Хай тобі грець... Покритий черепашками берсерк РОЗДОВБАВ УСЮ ЗДОБИЧ УЩЕНТ!"},{"a":"polonia","t":"Що, якір тобі в зябра, з тобою не так, чоловіче? Цей мотлох вартує безліч дублонів!"},{"a":"rudo","t":"Усе це застаріле. "},{"a":"rudo","t":"Воно магічне."},{"a":"rudo","t":"І, скоріш за все, прокляте."},{"a":"rudo","t":"Я все перетворюю на пил, щоб уберегти інших від проблем."},{"a":"rudo","t":"Якщо це місто таке дурне, щоб побачити проблему, я сам упораюся!"},{"a":"polonia","t":"Агов, чоловіче. Цей мотлох НАСПРАВДІ цінний. Ти ж не..."},{"a":"rudo","t":"Пф."},{"a":"rudo","t":"...Ай."},{"a":"polonia","t":"Заради кракена! Не треба просто ламати об коліно!"},{"a":"polonia","t":"...Хоча, здається, цей посох сам що завгодно зламає. На ньому ані подряпини!"},{"a":"polonia","t":"Як твоя нога, чоловіче?"},{"a":"rudo","t":"Нормально. Але посох видався міцнішим, ніж я думав."},{"a":"rudo","t":"Чомусь я не можу його відпустити. Приклеїли його до мене чи що."},{"a":"polonia","t":"Я, звичайно, не корабельний лікар, але тут схоже на добряче прокляття, чоловіче."},{"a":"polonia","t":"...Тобі б до лікаря звернутися."},{"a":"rudo","t":"Звичайно, це проклята магія. Це ЗАВЖДИ проклята магія."},{"a":"rudo","t":"Добре, я пішов. Доламай, що залишилося."},{"a":"polonia","t":"Так-так, чоловіче!"},{"a":"polonia","t":"...Не просто доламаю, але й увійду, адже пірат сьогодні влаштовує пограбування! Йо-хо-хо!"}]},{"id":"rudo_a","i":4,"title":"Жорстоке кохання","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"herbs","t":"Горза!"},{"a":"gems","t":"Горза!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Привіт, Джуніпер. І Мейлі! Як справи?"},{"a":"herbs","t":"Ми з Мейлі розмовляли про її майбутнього прекрасного принца..."},{"a":"gems","t":"Ох, не можу дочекатися!"},{"a":"herbs","t":"...І нам цікаво... Як ТИ зустріла свого?"},{"a":"wood","t":"Цього тупого здорованя Рудо? Ха!"},{"a":"wood","t":"Можливо, у це важко повірити, але цей чоловік знає, як розмовляти з панянками."},{"a":"wood","t":"Зараз пригадаю... Ось як усе було..."},{"a":"rudo","t":"...Ще один у дорогу."},{"a":"tavern","t":"Отже... Рудо. А ти не думав колись стати сімейною людиною?"},{"a":"rudo","t":"Не лізь не у свої справи, Найє. У мене немає на це часу."},{"a":"tavern","t":"Кохання приходить, коли ти цього зовсім не очікуєш! Хто знає, жінка твоєї мрії може увійти в будь-яку мить..."},{"a":"rudo","t":"Отакої! Я не заведу сім'ю з жінкою, яка не зможе покласти мене на лопатки."},{"a":"wood","t":"Це виклик, здоров'як?"},{"a":"rudo","t":"Спробуй, зубаста!"},{"a":"tavern","t":"Горзо, поклади стілець..."},{"a":"wood","t":"Як тобі таке, тупоголовий? Хочеш ще?"},{"a":"rudo","t":"РА-А-А-А!!!"},{"a":"wood","t":"Ого!"},{"a":"wood","t":"...А за тиждень ми одружилися. Найкривавіше весілля в історії."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"...М-мабуть треба ще когось запитати."}]},{"id":"rudo_05","i":5,"title":"Прокляття та напади","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Що ти маєш на увазі, кажучи «не можеш зламати»?!"},{"a":"master","t":"Саме те й маю, мій суровий друже. Не можу розбити цю реліквію."},{"a":"rudo","t":"Що за радість мати адамантіновий молот, якщо він не може розбити цю жалюгідну річ?"},{"a":"master","t":"Ну, авжеж, не мало... Виглядає, як саме зло!"},{"a":"master","t":"Як би там не було, ви маємо справу із чимось більшим. Можливо, з магією..."},{"a":"rudo","t":"ЗВИЧАЙНО це магія."},{"a":"rudo","t":"Це завжди проклята магія."},{"a":"master","t":"Здається, ти і сам про це знав! Чому б не звернутися до когось, хто в цьому розбирається, замість мене?"},{"a":"rudo","t":"Магам вірити не можна... Ані трохи."},{"a":"master","t":"Не думаю, що в тебе є вибір, синку."},{"a":"master","t":"Та і як можна не довіряти милій Лілу? Вона ж чарівна!"},{"a":"rudo","t":"Вона маг, чи що? Тобто вона така ж, як і інші."},{"a":"rudo","t":"Небезпечна. Злобна. ОГИДНА."},{"a":"master","t":"Ну, вона, можливо, єдина, хто може допомогти, якщо ти колись захочеш позбутися цього посоха."},{"a":"rudo","t":"...Дідько."}]},{"id":"rudo_06","i":6,"title":"Чарівник мимоволі","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Агов, Найє! Як завжди."},{"a":"tavern","t":"Вибач, Рудо, зі зброєю не пущу. Ти знаєш правила."},{"a":"rudo","t":"А-а, це? Це ж палиця."},{"a":"tavern","t":"Я так не думаю. Я впізнаю посох навіть у темряві!"},{"a":"rudo","t":"Пф-ф. Добре. Бачиш? Сила прокляття. Не можу його позбавитися."},{"a":"tavern","t":"Отакої! Думаю, в такому випадку, ми можемо зробити виняток. Тільки для тебе!"},{"a":"rudo","t":"Гм. Дякую!"},{"a":"tavern","t":"Так що будеш тепер робити?"},{"a":"rudo","t":"Не переймайся. Буду жити далі."},{"a":"tavern","t":"Невже? Ти став ще вибагливіше. Ну-у, якщо це взагалі можливо."},{"a":"tavern","t":"Та й дивлячись на тебе, складається враження, що ти якийсь маг."},{"a":"rudo","t":"...Насправді? Триклятий маг?"},{"a":"tavern","t":"Тобі тільки капелюшка бракує. І гарних манер!"},{"a":"rudo","t":"Може, воно й так. Треба щось вирішувати. До зустрічі!"},{"a":"tavern","t":"Гарного дня! Я запишу на твій рахунок."}]},{"id":"rudo_07","i":7,"title":"Проблиск травми","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Мені так за все жаль. Мені сказали, що... ти допоможеш з прокляттям."},{"a":"lilu","t":"Це посох, так? Виглядає кепсько!"},{"a":"lilu","t":"Мені не доводилося знімати прокляття, але в теорії... Має вийти."},{"a":"lilu","t":"Точно? Ніяких сумнівів? Відчуваю якусь напругу."},{"a":"rudo","t":"Добре..."},{"a":"lilu","t":"Ок! Дай зосередитися..."},{"a":"lilu","t":"Відчуваю прокляття... воно тебе огорнуло."},{"a":"lilu","t":"Почекай, потрібно ще придивитися..."},{"a":"rudo","t":"Аргх!.."},{"a":"lilu","t":"Ого!"},{"a":"lilu","t":"Здається, ще секунда, і від тебе прилетів би ляпас!"},{"a":"rudo","t":"Вибач... Я не спеціально."},{"a":"lilu","t":"Не думаю, що щось вийде. Треба більше концентрації, розумієш?"},{"a":"rudo","t":"Так. Вибач. Я пошукаю ще."},{"a":"lilu","t":"Може, спитати Хворобу? Є шанс, що вона зможе чимось допомогти."},{"a":"rudo","t":"Хвороба, да? Спробую."},{"a":"lilu","t":"Пам'ятай про манери! У неї... особливі обставини, про які варто знати..."}]},{"id":"rudo_08","i":8,"title":"Прокляття на двох","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Пані Хвороба, є хвилька?"},{"a":"malady","t":"(О ні, Лілу про нього попереджувала...)"},{"a":"malady","t":"Мені жаль... Не думаю..."},{"a":"rudo","t":"Перепрошую, лякати вас не хотілося. Дай, думаю, запитаю вас про посох."},{"a":"malady","t":"Я... мені здавалося, ви ненавидите магію?"},{"a":"rudo","t":"Більше за усе в цьому світі."},{"a":"rudo","t":"На вас також прокляття, чи не так? Таке ж, як на мені."},{"a":"rudo","t":"Ви не обирали магію. Це не ваша провина."},{"a":"malady","t":"У цьому випадку... спробую поговорити з посохом."},{"a":"malady","t":"..."},{"a":"malady","t":"...Він схожий на паразитів. Він годується вашою іскрою."},{"a":"rudo","t":"Хіба це не розумно?"},{"a":"malady","t":"Так... свого роду."},{"a":"malady","t":"У вас вкрай сильна іскра. Можливо, пройдуть роки, але..."},{"a":"malady","t":"Може, мені вдасться позбавити вас магії?.."},{"a":"rudo","t":"Гм. Упевненості ніякої."},{"a":"rudo","t":"Тобто, йому просто потрібне джерело магії, так?"},{"a":"malady","t":"Гм-м... так. Щось таке."},{"a":"malady","t":"Будь ласка... Мене вже й так прокляли, то..."},{"a":"rudo","t":"Ха! А так навіть й не скажеш, міс!"},{"a":"rudo","t":"Дякую за допомогу. Здається, в мене є ідея..."}]},{"id":"rudo_09","i":9,"title":"Минуле солдата","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"malady","t":"М-м... Можна увійти?"},{"a":"veteran","t":"А-а. Ви є та сама Медуза."},{"a":"veteran","t":"Заходьте, ходяча неприємність. Стільців вашого розміру, боюся, немає."},{"a":"malady","t":"Це нічого... Дякую. Хочу розпитати вас про одного чоловіка. Про Рудо."},{"a":"veteran","t":"Цього велетня? Він же не знущався над вами?"},{"a":"malady","t":"Ні, він був надзвичайно... добрий до мене."},{"a":"veteran","t":"Невже? Дивно. Він ненавидить магію."},{"a":"malady","t":"Ось чому я тут. Хотіла запитати... чому?"},{"a":"veteran","t":"Колись давно ми з ним служили в імперській армії. Давні товариші."},{"a":"veteran","t":"Рудо... «зголосився добровольцем» експерименту. Того самого, коли солдатам імплантували іскру."},{"a":"veteran","t":"Кепські справи були. Він через це змінився."},{"a":"malady","t":"Який жах... "},{"a":"veteran","t":"Жахливіше нікуди. Ми накивали звідти п'ятами при першій можливості."},{"a":"malady","t":"Але... це хоча б спрацювало? Я відчула в ньому неймовірно сильну іскру..."},{"a":"veteran","t":"Важко судити. Ти ж бачила його. Навіть сам імператор не зміг би змусити його вимовити найпростіше заклинання."},{"a":"malady","t":"А тепер і зовсім... на ньому це огидне прокляття... Я зможу допомогти?"},{"a":"veteran","t":"Він до тебе прийшов, чи не так? Його прохання про допомогу — хороший знак! "},{"a":"veteran","t":"Нехай він не найрозумніший, але парубок завзятий. Упевнений, він щось да придумає."}]},{"id":"rudo_10","i":10,"title":"Передача права власності","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"rudo","t":"Так, гаразд, ти, шматок дерева! Я тебе поріжу!"},{"a":"rudo","t":"Або передам ось тому гібліну!"},{"a":"monster_Forest_Blacksmith","t":"Ой! Пусти!"},{"a":"rudo","t":"Ти стаєш друзями з цією штуковиною, а ми забуваємо про те, що трапилося."},{"a":"rudo","t":"А якщо ти так не зробиш..."},{"a":"rudo","t":"Я стрибну в лаву і подивимося, хто з нас протримається довше."},{"a":"rudo","t":"Так що? «Водичка» така приємна!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"...Удалий вибір. Гібліне, веселися."},{"a":"monster_Forest_Blacksmith","t":"Аргх! Застрягло!"},{"a":"rudo","t":"Гуа-ха-ха-ха! Усього доброго!"}]},{"id":"rudo_epilogue","i":11,"title":"Епілог","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Рудо! Щодо того разу..."},{"a":"rudo","t":"Гм-м?"},{"a":"lilu","t":"О! Посох зник!"},{"a":"rudo","t":"Ага. Однією проблемою менше."},{"a":"rudo","t":"...Вибач за той раз. Нерви не витримували."},{"a":"lilu","t":"...Я вибачаю тебе. Але тобі варто переглянути своє відношення до магів."},{"a":"rudo","t":"Ха! Допомога Хвороби не була зайвою. Хтозна, може я й зміню відношення."},{"a":"lilu","t":"Їй вдалося зняти прокляття?"},{"a":"rudo","t":"Не зовсім. Але завдяки їй мені на допомогу прийшла... несподівана річ."},{"a":"rudo","t":"Трохи кооперації не завадило. Гуа-ха-ха-ха!"},{"a":"argon","t":"Ешлі, обережно! Щось наближається!"},{"a":"ashley","t":"Я готова до чого завгодно! Йди сюди, звірюга!"},{"a":"monster_Forest_Blacksmith","t":"...Допоможіть..."},{"a":"argon","t":"Га?"},{"a":"ashley","t":"Га-ааа?"}]}]},{"id":"atlab_sokka","name":"Сокка","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Великий воїн Сокка","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"atlab_aang","t":"А якщо... от так?"},{"a":"tavern","t":"О, милий трюк!"},{"a":"atlab_sokka","t":"Тьху. Він завжди так робить!"},{"a":"argon","t":"Привіт! Сокка, правильно? Я Аргон!"},{"a":"atlab_sokka","t":"О, салют. Якщо тобі потрібні трюки із чарами, це до Аанга."},{"a":"argon","t":"Та ні. Я не дуже знаюся на магії або чарах."},{"a":"argon","t":"У тебе спорядження ніби в грізного воїна."},{"a":"atlab_sokka","t":"Г-грізного воїна?"},{"a":"atlab_sokka","t":"Н-ну, ти маєш рацію! Я Сокка, великий воїн із команди аватара!"},{"a":"argon","t":"Я так і думав! Певно, ти знаєш силу-силенну неймовірних історій!"},{"a":"atlab_sokka","t":"Ще б пак! Наприклад, під час облоги Агна Кел'и..."},{"a":"atlab_sokka","t":"Ось так моя тодішня дівчина стала місячною."},{"a":"argon","t":"М-місячною?"},{"a":"atlab_sokka","t":"Еге ж. А потім флот народу вогню..."},{"a":"atlab_sokka","t":"...і бабах! Я повалив того здорового сича в біліотеці."},{"a":"argon","t":"Оце так! А хіба той сич не був могутнім духом?"},{"a":"atlab_sokka","t":"Саме так! Але із Соккою в складі команда Аватара завжди перемагає!"},{"a":"atlab_sokka","t":"До речі, а де Аанг?"},{"a":"argon","t":"А, та він пішов десь годину тому."},{"a":"atlab_sokka","t":"От дідько! Я геть утратив відлік часу. Пробач, Аргоне, мені пора!"}]},{"id":"atlab_sokka_02","i":2,"title":"Великий коваль Сокка","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"blacksmith","t":"Усе працюєш, Сокко?"},{"a":"atlab_sokka","t":"Привіт, Уоллесе. Дякую, що позичив мені свої інструменти!"},{"a":"blacksmith","t":"Дрібниці! Я здивований, що у своєму віці ти вже такий майстерний!"},{"a":"atlab_sokka","t":"Коли ти єдиний у своїй групі не вмієш повелівати стихіями, доводиться опановувати різні інші навички."},{"a":"atlab_sokka","t":"До того ж такі класні інструменти не щодня трапляються..."},{"a":"atlab_sokka","t":"Після роботи я миттю приведу їх у порядок!"},{"a":"blacksmith","t":"Оцей меч, який ти точиш... Звідки все це в тебе?"},{"a":"atlab_sokka","t":"Це мій космічний меч! Я сам викував!"},{"a":"blacksmith","t":"Із зоряного металу? Непогано, хлопче!"},{"a":"blacksmith","t":"Це має бути... щось позаземне!"},{"a":"atlab_sokka","t":"Ще б пак! Іншого такого меча немає!"},{"a":"polonia","t":"Ахой! Перепрошую за втручання, але чи не допоможе мені хтось із вас, славних парубків, підрихтувати мій вітрильник?"},{"a":"polonia","t":"Щось він сьогодні капризує. Наткнувся на якісь металеві кулі й викинувся на берег..."},{"a":"blacksmith","t":"І вийшло розбите корито!"},{"a":"atlab_sokka","t":"Жодних проблем! Я із племені води! Подивлюся, що можна зробити. Вибач, Уоллесе, я мушу йти!"},{"a":"blacksmith","t":"А тим часом я відремонтую решту твого спорядження. Щасти!"}]},{"id":"atlab_sokka_03","i":3,"title":"Великий штурман Сокка","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"atlab_sokka","t":"Ну ось, так хоча б безпечно дійдеш до порту."},{"a":"polonia","t":"Годящий ремонт. Усе надійно!"},{"a":"atlab_sokka","t":"...Я скріпив твоє кермо докупи виловленими з води дошками й шматками своєї сорочки."},{"a":"atlab_sokka","t":"Теж мені, «надійно». Скоріше на скору Соккину руку."},{"a":"polonia","t":"Йо-хо-хо! А як так вийшло, що ти не моряк, а вітрильники латаєш?"},{"a":"atlab_sokka","t":"Життя племені води — це човни й риболовля. Я ще на ногах ледь стояв, а вже ходив під вітрилами."},{"a":"atlab_sokka","t":"А недавно я навіть придумав підводного човна, який приводиться в дію водними чарами!"},{"a":"polonia","t":"Я не розумію цього сухопутного жаргону. Що воно таке?"},{"a":"atlab_sokka","t":"Це... ну, такий металевий човен, що плаває під водою."},{"a":"polonia","t":"Схоже, ти просто хочеш похоронити морських вовків на дні в прикольній бляшанці."},{"a":"engineer","t":"Ти сказав: «...Надзвичайно небезпечний прототип, який не пройшов тестування?»"},{"a":"atlab_sokka","t":"Е-е-е... не зовсім..."},{"a":"engineer","t":"Мені подобається твій стиль. Ходімо зі мною, новенький."},{"a":"polonia","t":"Йо-хо-хо, знову в море! Підняти якорі, поки тут немає мисливців за головами!"},{"a":"polonia","t":"Ар-р-р, цього разу краще ухилитися від плавучих металевих куль."}]},{"id":"atlab_sokka_04","i":4,"title":"Великий винахідник Сокка","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"engineer","t":"Уражаюче! Брехати не стану, твоє креслення не бездоганне..."},{"a":"engineer","t":"...Але як трохи погарувати, думаю, підводний човен попливе!"},{"a":"atlab_sokka","t":"Геніально, правда? Я так і знав!"},{"a":"atlab_sokka","t":"Але не слід забувати, що керувати ним зможуть лише повелителі води."},{"a":"engineer","t":"Це все деталі. Ми щось придумаємо."},{"a":"engineer","t":"Лише подумай! На цьому ми могли б дослідити затонулий храм!"},{"a":"atlab_sokka","t":"А ще в ньому не так багато повітря, тож подорож буде короткою."},{"a":"atlab_sokka","t":"...Ти мене чуєш?"},{"a":"engineer","t":"Не спирайся на цю велику металеву кулю."},{"a":"atlab_sokka","t":"..А? Ой! А чому?"},{"a":"engineer","t":"Це прототип морської бомби. Не чіпай. Вона дуже вибухонебезпечна."},{"a":"atlab_sokka","t":"...Ох."},{"a":"atlab_sokka","t":"У будь-якому разі тримай мене в курсі, як просувається робота над прототипом."},{"a":"atlab_sokka","t":"Якщо все вийде... ми знайдемо для нього застосування."}]}]},{"id":"sia","name":"Сія","chapters":[{"id":"sia_01","i":1,"title":"Перші кроки короля","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"king","t":"Сіє! Я прийняв рішення!"},{"a":"sia","t":"Так, мій король?"},{"a":"king","t":"Сьогодні я хочу піти по магазинах!"},{"a":"sia","t":"Чудова ідея, Ваша Величносте."},{"a":"sia","t":"Проте за планом, здається, ви сьогодні зустрічаєтеся з іноземними сановниками..."},{"a":"king","t":"Як нудно! А можна їх просто відправити геть?"},{"a":"sia","t":"Пам'ятайте, мій королю, хоча ви ще молоді, ви все одно король. Ваше слово — закон."},{"a":"king","t":"...Ти маєш рацію! По магазинах! Сановники можуть почекати!"},{"a":"sia","t":"Ваша рішучість захоплює. Вас супроводити?"},{"a":"king","t":"Звичайно! Я більше нікому не довіряю захист своєї величності."}]},{"id":"sia_02","i":2,"title":"Скрізь свої люди","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"...Таким чином, у мене є підстави вважати, що життя нашого короля наражається на небезпеку."},{"a":"elderowen","t":"Розумію. Насправді, кілька конкуруючих королівств можуть отримати зиск від замаху на короля."},{"a":"elderowen","t":"Я не бачив підозрілих осіб, але Найя з таверни, напевно, знає більше."},{"a":"sia","t":"Дякую, старійшино. Я дуже ціную вашу мудрість і патріотизм."},{"a":"elderowen","t":"Не варто. Мій обов'язок як громадянина забезпечувати процвітання короля."},{"a":"elderowen","t":"Хоча він ще молодий і дурний, я впевнений, що з Рейнгольда вийде чудовий король... із часом."},{"a":"sia","t":"І мій обов'язок — зробити так, щоб він до цього доріс!"},{"a":"tavern","t":"Так-так, нечасто ми бачимо блакитну кров у цій таверні!"},{"a":"sia","t":"Облиш, Найє, ти знаєш, хто я."},{"a":"tavern","t":"І то правда! Сіє Леонель, подарунок нашому королю від імператора Керна..."},{"a":"tavern","t":"Щоб бути не лише його радницею, але й слідкувати за ним, чи не так?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...А ти скрізь суєш свого носа."},{"a":"sia","t":"Що ж, скажи мені, довгоноса Найє..."},{"a":"sia","t":"Чи не бачила ти чужинців у своїй таверні останнім часом?"},{"a":"tavern","t":"О, у нас тут багато чужинців! П'яні орки, крамарі..."},{"a":"tavern","t":"Але найдивнішою є ось та дівчина в кутку — он там."},{"a":"yami","t":"...!"},{"a":"sia","t":"Вона зникла..."},{"a":"sia","t":"Це була азумська шпигунка! ...Чи навіть убивця."},{"a":"sia","t":"Мені треба бути дуже пильною..."}]},{"id":"sia_03","i":3,"title":"Незваний гість","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Ми зібрали вас тут сьогодні, щоб відсвяткувати неймовірну щедрість короля."},{"a":"sia","t":"За останні місяці він пожертвував кілька мільйонів золотом з власної скарбниці..."},{"a":"sia","t":"...Кільком місцевим храмам, школам і притулкам."},{"a":"sia","t":"Усіх запрошуємо на бенкет, розкажіть своїм друзям і рідним."},{"a":"sia","t":"Слава королю Рейнгольду!"},{"a":"yami","t":"Тиран Рейнгольд, настав кінець твоєму правлінню!"},{"a":"king","t":"А-а-а..."},{"a":"sia","t":"Сюрікен...! Азумська шпигунка!"},{"a":"sia","t":"Охорона! Оточити замок! Ніхто не має вийти!"},{"a":"sia","t":"Аргоне, дожени вбивцю!"},{"a":"argon","t":"Зрозуміло!"},{"a":"sia","t":"Ей, немитий блазень! Короля поранено! Негайно відшукай цілителя!"},{"a":"leather","t":"Як неввічливо, слухай."},{"a":"sia","t":"(У мене всі входи були під ретельним наглядом...)"},{"a":"sia","t":"(...Але хто ця дівчина?)"}]},{"id":"sia_04","i":4,"title":"Підпалені листи","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Довгоноса Найє, думаю, ти мусиш мені дещо пояснити."},{"a":"tavern","t":"О, пані Леонель... Думаю, це ВИ маєте мені дещо розповісти."},{"a":"sia","t":"Прошу?"},{"a":"tavern","t":"Я перехопила деякі ДУЖЕ цікаві листи. Думаю, вони відправлені вами."},{"a":"tavern","t":"Почитаємо разом?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Подивимося... Печатка Керна, адресовано особисто імператору Керну?"},{"a":"tavern","t":"Ой-йой. Я так сподівалася на скандальну любовну пригоду, але зрада — також непогано."},{"a":"sia","t":"Н-найє, досить!"},{"a":"tavern","t":"О, а тут найцікавіше!"},{"a":"tavern","t":"«Король Рейнгольд — повний дурень, чия присутність на троні дуже вам на користь»."},{"a":"tavern","t":"«Живий він зашкодить своєму королівству навіть більше, ніж мертвий»."},{"a":"sia","t":"..."},{"a":"tavern","t":"Мушу зазначити, такі некрасиві слова не личать його радниці!"},{"a":"sia","t":"Довгоноса... Найє... Ти за це заплатиш!"},{"a":"tavern","t":"Можливо, пізніше. Але зараз, думаю, ти заплатиш. Підозрюю, що немало."},{"a":"sia","t":"...Опускаєшся до шантажу?"},{"a":"tavern","t":"Це такий малий гріх у порівнянні зі зрадою!"},{"a":"tavern","t":"З іншого боку, якщо ви планували зашкодити нашому королю..."},{"a":"sia","t":"Хм. Ну добре. Назви свою ціну. І молись, щоб моя шпигунська мережа не перехитрила твою, Найє."},{"a":"tavern","t":"Чекаю з нетерпінням!"}]},{"id":"sia_a","i":4,"title":"Примха короля","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"sia","t":"Мій королю."},{"a":"king","t":"Привіт, Сіє! Чи можу допомогти?"},{"a":"sia","t":"У вас раптово не було останнім часом нападів вашої «примхливої» хвороби?"},{"a":"king","t":"Н-ні! Жодним чином! Як можна!"},{"a":"sia","t":"Дивно. Згідно з нашими бухгалтерськими записами, сховище №36 доверху заповнене <c1>кунаями</c1>."},{"a":"sia","t":"Не варто нагадувати Вашій Величності, що це надзвичайно рідкісний предмет."},{"a":"king","t":"Я... я впевнений, що це можна поясн..."},{"a":"sia","t":"Більше того, багато рідкісного антикваріату королівства бачили в простолюдинів."},{"a":"sia","t":"Ваша щедрість гідна схвалення..."},{"a":"sia","t":"...Але прошу, утримуйтеся від роздачі безцінних артефактів через зміни настрою."},{"a":"king","t":"Пф. Ну добре! Із сьогоднішнього дня я — зовсім нова людина!"},{"a":"sia","t":"Дякую за розуміння. Мені треба йти."},{"a":"king","t":"Моя воля непохитна! Мені не потрібні матеріальні цінності!"},{"a":"king","t":"...У цьому інтер'єрі не вистачає кількох <c1>королівських клинків</c1>, чи не так?"}]},{"id":"sia_05","i":5,"title":"Агент Лебідь","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"«...Події розвивалися непередбачувано, і на життя короля Рейнгольда стався замах."},{"a":"sia","t":"Здається, за цим замахом стоїть Азума. Агент Лебідь займеться розслідуванням»."},{"a":"king","t":"Сіє! Що ти робиш?"},{"a":"sia","t":"О, просто пишу листа, не звертайте уваги."},{"a":"sia","t":"(Звітую імператору Керна, ось що...)"},{"a":"king","t":"Добре! Іноземні сановники чекають на мою особу."},{"a":"king","t":"Можливо, вони трохи... ображені через мій минулий похід по магазинах."},{"a":"king","t":"Я був би дуже радий, якщо б ти мені допомогла владнати цю ситуацію!"},{"a":"sia","t":"Звичайно. Буду там за мить, мій королю."},{"a":"sia","t":"Якщо повідомити імператору Керну про цю спробу вбивства, це може призвести до неприємних наслідків..."},{"a":"sia","t":"Мені... треба час, щоб подумати. Це королівство ще... не готове зустріти Керн."},{"a":"sia","t":"Заради спільної безпеки... Думаю, треба не згадувати про це..."},{"a":"sia","t":"«Усе відбувається за планом. В агента Лебедя немає новин цього місяця»."}]},{"id":"sia_06","i":6,"title":"Троянди і шипи","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"king","t":"Сіє! До тебе прийшов відвідувач! Виглядає доволі шляхетно, маю зазначити."},{"a":"sia","t":"...Шляхетно, мій королю? Це ж не..."},{"a":"donovan","t":"Пані Сіє."},{"a":"sia","t":"...Доноване."},{"a":"sia","t":"Мій королю, у скарбниці на вас чекає термінова справа. Я б порекомендувала вам негайно зайнятися нею."},{"a":"king","t":"А вже прийшла нова партія чистого золота? Не можу чекати!"},{"a":"donovan","t":"Ну що за дурень цей король, чи не так?"},{"a":"sia","t":"Якими вітрами ти опинився в королівстві Рейнгольда, алхіміку?"},{"a":"donovan","t":"Як завжди, одразу до справи, агенте Лебедю."},{"a":"donovan","t":"У мене просто відпустка. З дозволу імператора Керна, звичайно."},{"a":"donovan","t":"Понюхати квіти, скуштувати зілля... Така собі відпустка алхіміка."},{"a":"sia","t":"І з усіх місць ти обрав це?"},{"a":"donovan","t":"Здається, у цьому недокоролівстві є багато вмілих алхіміків."},{"a":"donovan","t":"...Проте якщо виявиться, що лебедина вірність уже не така стійка..."},{"a":"sia","t":"Я тебе зрозуміла, Доноване. Можеш продовжувати насолоджуватися... відпусткою."},{"a":"donovan","t":"Як побажаєш, пані Сіє. Було приємно поспілкуватися."},{"a":"sia","t":"...Чергова шпилька в мій бік."}]},{"id":"sia_07","i":7,"title":"Незнайомка із золотого міста","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Донован? Сподіваюся, я не завадила... шпигунству."},{"a":"donovan","t":"О! Пані Сія!"},{"a":"donovan","t":"Це не те, що ти подумала. Я просто тут оглядаюся."},{"a":"sia","t":"Не варто бути таким скритним. У Загубленому золотому місті всім раді."},{"a":"sia","t":"Але пам'ятай, що за законами королівства все <c1>чисте золото</c1>, знайдене тут, належить королю Рейнгольду."},{"a":"sia","t":"Натомість хоробрі шукачі пригод отримують винагороду за свій внесок."},{"a":"donovan","t":"Розумію. Дуже... щедрий правителю."},{"a":"donovan","t":"Потім <c1>чисте золото</c1> перетворюється на монети, що викликає стрімку інфляцію..."},{"a":"sia","t":"Саме так. Бачу, що ти перехоплюєш мої листи до імператора."},{"a":"donovan","t":"Я люблю все знати."},{"a":"sia","t":"Оскільки ти тут, зроби корисну справу та віднеси трохи <c1>чистого золота</c1> назад до замку."},{"a":"donovan","t":"Звичайно. Усе для тебе, пані."},{"a":"sia","t":"Дивись, не зламай ніготь, коли будеш повертатися, любий Доноване."}]},{"id":"sia_08","i":8,"title":"На перехресті долі","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"tavern","t":"Мій маленький Лебідь повернувся! Дуже пунктуальний, як і очікувалося від найкращого адміністратора."},{"a":"sia","t":"Я відповіла на твій виклик, довгоноса Найя. В мене поганий настрій, тож не зволікай."},{"a":"tavern","t":"Тоді приготуйтеся! Я перехопила пошту якогось алхіміка..."},{"a":"tavern","t":"А також експрес-магопошту! Ви не повірите, як важко було її отримати!"},{"a":"sia","t":"Ти ж не вважаєш, що..."},{"a":"tavern","t":"Мені здається, що цей Донован прийняв правила гри."},{"a":"sia","t":"Якщо лист у тебе, тоді..."},{"a":"tavern","t":"Так, його ніхто не отримає! Якщо заплатите, звісно."},{"a":"sia","t":"Я... добре. Назви ціну, Найя. Я заплачу."},{"a":"tavern","t":"Я підняла звичайний тариф. За це я прошу особливу винагороду."},{"a":"sia","t":"...Дуже добре. Мені потрібно—"},{"a":"tavern","t":"Оберіть сторону, Сія. Ось моя ціна."},{"a":"sia","t":"..."},{"a":"tavern","t":"Грати на обидві сторони — небезпечно... і, здається, ви заплуталися у цій павутині."},{"a":"tavern","t":"Звичайно, залежно від вашої відповіді я можу допомогти..."}]},{"id":"sia_09","i":9,"title":"Ланцюжок зради","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Любий Донован. В мене є до тебе прохання."},{"a":"donovan","t":"О? Я уважно слухаю."},{"a":"sia","t":"Завітай до Імператора і скажи йому, що агент Лебідь мертвий. Він загинув трагічною та почесною смертю на службі Імперії."},{"a":"donovan","t":"Ч-чого?"},{"a":"sia","t":"Я кидаю роботу, Донован. Переходжу на іншу сторону, якщо так більш зрозуміло."},{"a":"sia","t":"І саме ти розповіси про це. Звісно, підтримавши мою історію."},{"a":"donovan","t":"М-маячня! Це ж зрада! Я ніколи не зроблю..."},{"a":"sia","t":"Зробиш, Донован, зробиш. Якщо, звісно, не хочеш, щоб увесь світ довідався рецепт твого еліксиру безсмертя."},{"a":"donovan","t":"А, то все, що ти можеш — блефувати, Сіа? Я ніколи нікому його не розповідав. Ти не можеш..."},{"a":"sia","t":"Що ж там було? Так, крильця сторічної одноденки... вода зі Стіксу?..."},{"a":"donovan","t":"А-але ж це..."},{"a":"sia","t":"Там було так багато інгредієнтів... навіть, здається, трошки вина для смаку?"},{"a":"donovan","t":"М-мовчи! ДОСИТЬ! Не знаю, якими темними силами тобі вдалося про це довідатися..."},{"a":"sia","t":"Здається, ти недооцінюєш мою шпигунську мережу."},{"a":"donovan","t":"...Але добре, я підіграю тобі. Цього разу."},{"a":"sia","t":"Не вміємо програвати, так? Я вважаю, що мої умови є більш ніж щедрими."},{"a":"sia","t":"Лише одна маленька зрада в обмін на роботу всього життя?"}]},{"id":"sia_10","i":10,"title":"Посмертна допомога","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Агенте Шепіт. Це я."},{"a":"essence","t":"*позіхає*... так швидко?"},{"a":"sia","t":"Ваша інформація була точною. Дякую вам за блискучу роботу."},{"a":"essence","t":"На... здоров'я..."},{"a":"sia","t":"Донован завжди був обережною людиною, але я вважаю, що привид може пролізти де завгодно!"},{"a":"essence","t":"Абсолютно..."},{"a":"essence","t":"Він виглядав... таким розлюченим..."},{"a":"sia","t":"Як і домовлялися, залишу оплату на могилі як підношення."},{"a":"sia","t":"Я навіть дещо додав. Будь ласка, йдіть і подіставайте Донована ще трошки."},{"a":"essence","t":"Мені платять за... усі ці примарні штучки. Прекрасно."}]},{"id":"sia_11","i":11,"title":"Вільний політ лебедя","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"king","t":"Сія! Я ледве тримаюся! Скільки ще мені приховувати свої примхи від усього світу?!"},{"a":"sia","t":"Минуло лише кілька днів, Ваша Величносте. Будь ласка, зачекайте ще трохи."},{"a":"king","t":"Ах! Що може бути у всіх цих паперах?"},{"a":"sia","t":"Свідоцтва про народження та інші важливі адміністративні документи."},{"a":"sia","t":"Здається, випадково так сталося, що багато документів, які стосуються мого життя в цьому королівстві, зникли."},{"a":"sia","t":"Тому я старанно заповнював ці форми напам’ять."},{"a":"king","t":"Звісно! Мій найкращій порадник має офіційно бути підданим мого королівства!"},{"a":"king","t":"Ось! Я швидко поставлю на них свою королівську печать!"},{"a":"king","t":"Готово! Від тебе, як завжди, не сховається жодна деталь!"},{"a":"sia","t":"Дякую, Ваша Світлість. Я сподіваюся служити вам ще багато десятків років."},{"a":"king","t":"Ні на що менше я й не сподіваюся!"},{"a":"king","t":"Сія, я що, бачу сльози? Заповнення паперів справді сповнює тебе радістю?"},{"a":"sia","t":"Ах... ні. Насправді, ця паперова тяганина набридла мені до сліз."},{"a":"sia","t":"Отже! Поговоримо про ваші примхи?"},{"a":"king","t":"Давай! На мій погляд, поточна ситуація з щитом..."}]}]},{"id":"leather","name":"Тамас","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Привіт, приятелю. Думаю, досить мені бути захисником."},{"a":"leather","t":"Це значно відповідальніше, ніж я думав, приятелю. Мені вже зі шкірою працювати ніколи!"},{"a":"leather","t":"Може, наступного року спробую знову, приятелю. Побачимося в місті!"}]},{"id":"leather_01","i":1,"title":"Шкіра й дерево","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"leather","t":"Дякую за допомогу, приятелю."},{"a":"argon","t":"Немає за що, Тамасе! Ого, скільки шкіри!"},{"a":"leather","t":"Так, сьогодні партія чимала. А ти дивись під ноги."},{"a":"argon","t":"Так... Тут легко зашпортнутися... Ой!"},{"a":"leather","t":"Ой! Ай!"},{"a":"argon","t":"Вибач, Тамасе! З тобою все добре?"},{"a":"leather","t":"Трохи голову забив, приятелю. Здається, усе добре."},{"a":"leather","t":"...У мене тут промайнула геніальна думка, приятелю."},{"a":"leather","t":"Тому маю йти, приятелю. Це важливо."},{"a":"argon","t":"Е-е-е, звичайно! Був радий допомогти!"},{"a":"argon","t":"...А що ж мені тепер робити зі всією цією розкиданою шкірою...?"}]},{"id":"leather_02","i":2,"title":"Як передрікало пророцтво","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"leather","t":"Ось так я і коцнувся макітрою, приятелю. Ось тут невеличка гулька вискочила."},{"a":"mana","t":"Твої слова почуті, але допомоги не чекай."},{"a":"mana","t":"Потоки ефіру виявляють і пророкують, але не лікують."},{"a":"leather","t":"Але ж це все одно магія? Давай, приятелю, торкнися до неї своїми чарівними руками."},{"a":"mana","t":"Тут немає..."},{"a":"mana","t":"!!!..."},{"a":"mana","t":"Це... доля!.. Вона нездоланна!.."},{"a":"leather","t":"Точно все вийшло, приятелю? У мене ще паморочиться голова."},{"a":"mana","t":"...Перепрошую. Мені було видіння, і тепер треба помедитувати."},{"a":"mana","t":"Знайди фаворита Богині для зцілення... ран. А я маю негайно зникнути."},{"a":"leather","t":"Гаразд, приятелю. Мабуть, я просто піду собі, бо відчув прилив сил."}]},{"id":"leather_03","i":3,"title":"Згуртовані захисники","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"argon","t":"Отже, у місті з'явився новий... е-е-е... захисник."},{"a":"polonia","t":"Йо-хо-хо! Сподіваюся, він красень!"},{"a":"leather","t":"Привіт, приятелі!"},{"a":"polonia","t":"Якір мені в пельку! Ти жартуєш?"},{"a":"lilu","t":"Тамас?! Коли ти..."},{"a":"leather","t":"Та ось вирішив спробувати побути захисником, приятелю. Здається, нічого складного."},{"a":"argon","t":"Е-е-е... Тамасе, може, розкажеш, чим ти займаєшся?"},{"a":"leather","t":"Дубашу монстрів, друже. А ще в мене собачий нюх на всякі шкіряні речі."},{"a":"polonia","t":"Гей! Красти — це МОЯ фішка! Вигадай якусь іншу!"},{"a":"leather","t":"Я не краду, приятелько. Люди просто залишають свої речі то там, то сям."},{"a":"lilu","t":"Скоро тут стане доволі цікаво!"},{"a":"polonia","t":"Ар-р-р, може, й так..."}]},{"id":"leather_04","i":4,"title":"Неоспіваний герой","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетони фортуни"},"side":false,"lines":[{"a":"sia","t":"Мій королю, маю для вас дуже незвичайне повідомлення."},{"a":"king","t":"Я тебе уважно слухаю! Продовжуй!"},{"a":"sia","t":"Герої та подорожні повідомляють, що на дорогах безпечно, як ніколи."},{"a":"sia","t":"Монстри порозбігалися і, здається, навіть не насмілюються нападати."},{"a":"king","t":"Чудова новина!"},{"a":"sia","t":"Однак ми ніяк не збагнемо причину такої дивної поведінки."},{"a":"sia","t":"Не менш дивним є і несподіване падіння цін на вироби зі шкіри..."},{"a":"king","t":"Я впевнений, що це просто збіг! Давай улаштуємо бенкет на честь гарної новини!"},{"a":"sia","t":"Можливо, мій королю... можливо."}]}]},{"id":"malady","name":"Хвороба","chapters":[{"id":"malady_01","i":1,"title":"Увічнено в камені","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Квест виконано! Дітлахи! В цілості й схоронності!"},{"a":"argon","t":"Руїни Хроноса не призначені для ігор."},{"a":"argon","t":"Мабуть, і мені пора звідси вибиратися!"},{"a":"malady","t":"...Сподіваюся, злі гібліни відстали від мене на сьогодні."},{"a":"argon","t":"А, вітаннячко, міс! Ви загубилися?"},{"a":"malady","t":"Н-не... не підходьте!"},{"a":"argon","t":"Га?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Якщо будеш довго дивитися мені в очі, обернешся каменем! Це через прокляття Медузи."},{"a":"malady","t":"Хоча... здається, ти добрий."},{"a":"malady","t":"Мені жаль..."}]},{"id":"malady_02","i":2,"title":"Він у мармурі","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"*Гм-мпф* Старійшина Оуен..."},{"a":"elderowen","t":"Лілу! Що ти робиш зі статуєю? Куди тягнеш?"},{"a":"elderowen","t":"Це статуя.... Аргона?!"},{"a":"lilu","t":"Пф-ф... Пф-ф... Це ДІЙСНО статуя Аргона!"},{"a":"elderowen","t":"Ой, лишенько. Став каменем, чи не так?"},{"a":"lilu","t":"Вочевидь. Я знайшла його в такому вигляді в руїнах Хроноса."},{"a":"lilu","t":"Добре ще, що Рудо трохи допоміг його дотягнути!"},{"a":"elderowen","t":"Ось така неприємність. Ти його врятуєш?"},{"a":"lilu","t":"Напевно! Але інгредієнти дуже рідкісні. Їх непросто дістати."},{"a":"lilu","t":"Я зберу містян. І крамаря покличу! Залишу Аргону тобі."},{"a":"elderowen","t":"Авжеж. Хлопчику мій, сподіваюся, ти не проти побути садовою прикрасою."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Ах! Дурні голуби! Киш!"}]},{"id":"malady_03","i":3,"title":"Око за око","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"...Ця лоза не дасть занудьгувати. З цього мало що залишилося."},{"a":"lilu","t":"Так, далі... Кров медузи. Буде нелегко."},{"a":"malady","t":"Гм-м..."},{"a":"lilu","t":"Ой! Чудовисько!"},{"a":"malady","t":"...Ти друг цієї людини, так?"},{"a":"lilu","t":"Аргона? Стоп. Так це ТВОЇХ рук справа?"},{"a":"lilu","t":"Так, тепер все значно спростилося. Мені потрібна крапелька крові Медузи..."},{"a":"malady","t":"Будь ласка, ні! Я не бажаю зла."},{"a":"lilu","t":"Ага! Ти перетворила його на камінь!"},{"a":"malady","t":"Мені жаль... Мені стало страшно, і наші погляди зустрілися."},{"a":"malady","t":"Усе в голові перемішалося... Ніхто не був таким добрим до мене."},{"a":"lilu","t":"Ох же ж... Несолодко тобі довелося."},{"a":"malady","t":"Якщо тобі потрібна кров... Я дам тобі трохи."},{"a":"malady","t":"А натомість... будь ласка, візьми мене з собою. Я хочу вибачитися перед ним."},{"a":"lilu","t":"Добре. Мені не подобається ця ідея. Ну, якщо я перетворюся на камінь, не думаю, що Донован буде нас рятувати."},{"a":"lilu","t":"Я за тобою стежу. А ти, навпаки, на мене не дивись!"},{"a":"malady","t":"Добре... Дякую."}]},{"id":"malady_04","i":4,"title":"Кров і плоть","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Готово! Це зілля має спрацювати. Шльоп-шльоп!"},{"a":"argon","t":"Аааа! Як же гарно випростатися!"},{"a":"argon","t":"Так, а що взагалі сталося?"},{"a":"lilu","t":"Хвороба перетворила тебе в камінь. Випадково. І хоче вибачитися."},{"a":"malady","t":"П-привіт. Мені так жаль... Я не хотіла...."},{"a":"argon","t":"Ну-у, лихо минуло. Відчуваю себе чудово. М'язи хіба що оніміли."},{"a":"argon","t":"Ти Хвороба? Мене звати Аргон. Приємно познайомитися!"},{"a":"argon","t":"О, твоя пов'язка злізла Давай поправлю."},{"a":"lilu","t":"Аргон! Ні!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Аргон... Доведеться пояснити йому дещо про медуз..."},{"a":"malady","t":"О ні! Мені жаль!"},{"a":"lilu","t":"Не переймайся. Це його провина."},{"a":"malady","t":"Можу пожертвувати кров'ю знову."},{"a":"lilu","t":"Я не дуже розбираюся в анатомії медуз, але нам варто почекати пару днів, поки ти відновишся."},{"a":"lilu","t":"А доти нікуди не йди. Небезпечно розгулювати наодинцы майже без сил."},{"a":"lilu","t":"Хоча, враховуючи твої... здібності, напевно, краще переговорити зі старійшиною Оуеном."},{"a":"malady","t":"Добре..."}]},{"id":"malady_05","i":5,"title":"Ласкаво просимо додому!","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Старійшина Оуен, ми повернулися!"},{"a":"elderowen","t":"Аргона врятували? Чудові новини!"},{"a":"lilu","t":"Е-е-е... не зовсім... Але..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"Хай захистить нас богиня!.. Медуза? Тут?!"},{"a":"lilu","t":"Це Хвороба. Вона допомогла вилікувати Аргона."},{"a":"lilu","t":"Їй потрібно залишитися тут на деякий час. Відновитися."},{"a":"elderowen","t":"Зрозуміло. Від тебе віє добром. Вибач за таку реакцію, Хвороба."},{"a":"malady","t":"Це через прокляття. Мене усі ненавидять. Навіть інші монстри. Я вже звикла."},{"a":"elderowen","t":"У стінах нашого міста ми завжди раді вітати тих, хто готовий служити на благо."},{"a":"malady","t":"Чесно?"},{"a":"elderowen","t":"За умови, що ти закриєш очі чимось. Так проблем не буде."},{"a":"elderowen","t":"Хворобо... Мабуть, тут тобі буде краще, ніж серед собі подібних."},{"a":"malady","t":"Дякую. Мене завжди звідусіль гнали геть..."},{"a":"elderowen","t":"Обов'язково сходи до крамаря. Там завжди знайдеться робота для всіх."},{"a":"lilu","t":"Точно! Можеш піти з нами на завдання."},{"a":"malady","t":"Я... Дякую, Лілу та Оуене!"}]}]},{"id":"hemma","name":"Хемма","chapters":[{"id":"hemma_01","i":1,"title":"Нависла тінь","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"hemma","t":"...І тоді Гіблін поліг, але перед цим устиг завдати декілька ударів моїм супутникам."},{"a":"hemma","t":"Будь ласка, подбай про них."},{"a":"priest","t":"Звичайно ж. Я негайно оброблю їхні рани."},{"a":"lilu","t":"Привіт! Я чула, що в місті з'явився новий заклинатель."},{"a":"lilu","t":"Я — Лілу! Приємно познайомитися!"},{"a":"hemma","t":"Ти маєш рацію, юна Лілу. Нас звати Хемма. "},{"a":"lilu","t":"...«Нас»?"},{"a":"hemma","t":"...Так. Заняття некромантією не проходять безслідно..."},{"a":"hemma","t":"Частина особистості залишається за Завісою, а решта сутностей переступає поріг..."},{"a":"hemma","t":"Ці сили... нас змінили. На краще, звичайно ж."},{"a":"lilu","t":"Кажете некромантія?! Але ж це... небезпечно?"},{"a":"hemma","t":"Надзвичайно. Але нас більше не задовольняють прості фокуси."},{"a":"hemma","t":"А тепер я маю йти. Нас чекають в іншому місці. Прощавай."},{"a":"lilu","t":"Некромантія... Це якийсь різновид чорної магії, Поллуксе! Але я вперше зустрічаю її представника наживо!"},{"a":"lilu","t":"Не сказати, що вона така вже лиха... Правда?"}]},{"id":"hemma_02","i":2,"title":"За будь-яку ціну","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"elderowen","t":"Некромант?.."},{"a":"elderowen","t":"Навіть не знаю, що про все це думати..."},{"a":"hemma","t":"Ви не дарма хвилюєтеся. Некромантія — це небезпечне мистецтво, коли поглинаються малозначні істоти..."},{"a":"hemma","t":"Але ми жодним чином не малозначні."},{"a":"elderowen","t":"А як щодо шукачів пригод, які йдуть із вами? Ви не висмоктуєте з них життя, щоб посилити свої чари?"},{"a":"hemma","t":"Лише з їхньої згоди. Ця дія є тимчасовою."},{"a":"hemma","t":"До того ж ми щедро платимо їм за послуги."},{"a":"elderowen","t":"Урешті-решт, я вважаю, що ви все ж робите добро..."},{"a":"elderowen","t":"Дуже добре. Гадаю, ви можете отримати статус офіційного захисника нашого міста."},{"a":"hemma","t":"Ваше схвалення нам не потрібне... але ми вдячні."},{"a":"elderowen","t":"А що привело вас у наше місто?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Ми просто шукаємо знання й силу. "},{"a":"hemma","t":"Маємо... одне завдання."},{"a":"elderowen","t":"Якось це все дуже туманно..."},{"a":"hemma","t":"Таким воно й залишиться. Прощавайте."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"Стільки смутку в цих очах..."}]},{"id":"hemma_03","i":3,"title":"Ворог усередині","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"herbalist","t":"...Недозріле живе коріння й надщільна моторошна ектоплазма. Щось іще?"},{"a":"hemma","t":"Це все. Решту купимо в крамниці."},{"a":"herbalist","t":"Дякую, заходьте ще!"},{"a":"hemma","t":"<c4>...Не забудь про грізні кігті.</c4>"},{"a":"hemma","t":"О, точно. Два грізні кігті, будь ласка."},{"a":"herbalist","t":"...І що це було?"},{"a":"hemma","t":"Не зважай. Скажімо так, просто пасажир."},{"a":"hemma","t":"<c4>Випусти-мене-випусти-мене-випусти-мене-випусти-мене.</c4>"},{"a":"hemma","t":"Тьфу. Та вгамуйся ти."},{"a":"hemma","t":"Решти не потрібно. Прощавай."},{"a":"herbalist","t":"...Дякую за чайові... і кошмари."}]},{"id":"hemma_a","i":3,"title":"Серед безсмертних","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетони фортуни"},"side":true,"lines":[{"a":"donovan","t":"Недозріле живе коріння? Цікавий вибір."},{"a":"hemma","t":"А що тут такого?"},{"a":"donovan","t":"Живе коріння — потужний реагент для багатьох магічних засобів, пов'язаних з молодістю й подовженням життя."},{"a":"donovan","t":"Ти, часом, не алхімік? Може, шукаєш засобів для довголіття?"},{"a":"hemma","t":"...Запитуєш у жінки про її вік? Як... непристойно."},{"a":"hemma","t":"Ми не алхімік. Криваві жертви значно ефективніші."},{"a":"donovan","t":"А, некромантія! Сфера діяльності, яка заслуговує поваги, але незбагненна."},{"a":"hemma","t":"Щодо нашого віку... ми вже давно перестали рахувати свої роки."},{"a":"donovan","t":"Мені це знайомо. Після перших кількох сотень років десятиріччя так і летять!"},{"a":"donovan","t":"Серед усіх цих одноденок стає самотньо, чи не так?"},{"a":"hemma","t":"Нам не самотньо. А тобі не варто пхати носа в справи некроманта."},{"a":"donovan","t":"Звісно ж. Я не збирався втручатися. Прощавайте!"},{"a":"donovan","t":"Дивна некромантка... Цікаво, ми раніше зустрічалися?"},{"a":"donovan","t":"...Ферлін?"}]},{"id":"hemma_04","i":4,"title":"Екзорцизм","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Спокійно, Хеммо. Це я! А зі мною Фрейя!"},{"a":"priest","t":"Хемма, так? Прошу, розслабся. Проймися силою екзорцизму..."},{"a":"hemma","t":"Щось не пригадуємо, щоб ми просили тебе про допомогу."},{"a":"hemma","t":"<c4>Забирайтеся звідси, дітки. Я нікуди не йду.</c4>"},{"a":"lilu","t":"А-а-а-а! Воно бере верх! Швидше, Фрейє!"},{"a":"priest","t":"Я... не можу! Щось блокує мої молитви..."},{"a":"hemma","t":"Це ми. Припини."},{"a":"priest","t":"Ви... прийняли цього злого духа з доброї волі?!"},{"a":"hemma","t":"Мушу визнати, із часом він став трохи дратівливим."},{"a":"hemma","t":"<c4>Насправді, я — жертва! Випустіть мене!</c4>"},{"a":"hemma","t":"Ох. Радше грубий, ніж злий, запевняю вас."},{"a":"hemma","t":"Це тебе не стосується. Будь ласка, не втручайся, Фрейє."},{"a":"priest","t":"Ох уже ці некроманти... завжди граються із силами, яких не розуміють!"},{"a":"lilu","t":"Усе гаразд, Фрейє! Я впевнена, вона знає, що робить!"},{"a":"lilu","t":"...Правда?"}]},{"id":"hemma_05","i":5,"title":"Роздвоєння особистості","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"hemma","t":"<c4>Здається, правда знову вилізла назовні. Готова забиратися з міста?</c4>"},{"a":"hemma","t":"Це все через ТЕБЕ. Треба було поводитися тихіше — і тоді все було б простіше."},{"a":"hemma","t":"Тим не менш ми поки що залишаємося тут. Це місто вселяє надію."},{"a":"hemma","t":"<c4>Ну добре. Так, може, випустиш мене хоча б разок?</c4>"},{"a":"hemma","t":"Нізащо. Тебе й так важко контролювати."},{"a":"hemma","t":"<c4>Випусти-мене-випусти-мене-випусти-мене-випусти-мене.</c4>"},{"a":"hemma","t":"Я роблю це заради тебе, Клоде."},{"a":"hemma","t":"...Пам'ятай це."}]},{"id":"hemma_06","i":6,"title":"Спадок брехні","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Ферлін!"},{"a":"hemma","t":"Що?"},{"a":"lilu","t":"Я так і знала! Хемма — це вигадане ім'я! Ти — монстр Ферлін!"},{"a":"hemma","t":"Ой лишенько! Отже в нас тут завівся підступний маленький брехунець."},{"a":"hemma","t":"Так і є. З домашнім завданням ти впоралася."},{"a":"hemma","t":"Можливо, ти також чула про Навіжену Аріель або Пропащу Астрід?"},{"a":"lilu","t":"...Я про них читала... але вони зникли кілька десятків років тому! Не може бути, щоб..."},{"a":"hemma","t":"Вони теж наші. На жаль, нас усюди переслідують, і імена використовувати не можна..."},{"a":"lilu","t":"Ти — монстр! Тебе необхідно зупинити!"},{"a":"hemma","t":"І як ти це зробиш? Хемма не вчинила нічого поганого. Хто повірить твоїм дивним казкам?"},{"a":"hemma","t":"Хіба що ти збираєшся зупинити мене самотужки..."},{"a":"lilu","t":"...Хм!"}]},{"id":"hemma_07","i":7,"title":"Зрощення душі","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"hemma","t":"Усе шпигуєш?"},{"a":"lilu","t":"За тобою стежу. І прислухаюся до твоїх підозрілих монологів..."},{"a":"hemma","t":"О, до речі. Познайомся, це Клод, мій чоловік. Він знав і кращі часи."},{"a":"hemma","t":"<c4>Я хочу вийти!</c4>"},{"a":"lilu","t":"...Що з ним сталося?"},{"a":"hemma","t":"Жахливий некромантичний випадок. Через безглузду помилку він опинився на межі смерті."},{"a":"hemma","t":"З урахуванням важкого тягаря наших земних гріхів у загробному житті нас, некромантів, не чекає нічого доброго..."},{"a":"hemma","t":"Тіло Клода зберегти не вдалося, але ціною неймовірних зусиль... ми зберегли його душу."},{"a":"lilu","t":"Зрощення душі? Але ж це заклинання потребує років досліджень, щоб підготувати відповідну ємність..."},{"a":"hemma","t":"Саме так. За наших обставин нам довелося імпровізувати."},{"a":"lilu","t":"Імпровізувати? Маєш на увазі... ти прив'язала душу Клода до себе?!"},{"a":"lilu","t":"Тіло не витримає двох душ! Це викликало б..."},{"a":"hemma","t":"...страшенний біль, божевілля. Таке й уявити неможливо."},{"a":"lilu","t":"Хеммо, навіщо?.. Як?.."},{"a":"hemma","t":"Усе просто, моя маленька Лілу. Програвати... для мене неприйнятно."}]},{"id":"hemma_08","i":8,"title":"Доручення століття","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"lilu","t":"Це занадто сильно для звільнення душі... Мабуть, її можна було б прив'язати до чогось іншого?.."},{"a":"hemma","t":"Ти вкрай люб'язна. Зацікавилася некромантією?"},{"a":"lilu","t":"Ні! Я ненавиджу тебе й все, що ти зробила!"},{"a":"lilu","t":"...Просто мені здається, що якщо цей Клод звільниться, це буде велика халепа для всіх нас."},{"a":"lilu","t":"Я просто намагаюся запобігти цьому, от і все!"},{"a":"hemma","t":"Шляхетно. Але дитя, таке як ти, може допомогти?"},{"a":"lilu","t":"Щоб приготувати належну ємність, потрібні багаторічні дослідження, а ще й матеріали..."},{"a":"hemma","t":"Це не проблема. Поглянь."},{"a":"lilu","t":"...! Як ти все це дістала?.. Навіть чорні діаманти!"},{"a":"hemma","t":"Ми не байдикували. Знадобилися десятиліття. У нас мало часу."},{"a":"hemma","t":"Залишилося знайти підхоже місце для ритуалу. Ми побоюємося, що його, може, і не існує."},{"a":"lilu","t":"Правильно. Душі потрібна духовна прив'язаність до певної місцевості, інакше нічого не вийде."},{"a":"hemma","t":"<c4>Або можна просто звільнити старого доброго Клода Фавія. Нехай собі бігає! Він знайде багато друзів!</c4>"},{"a":"lilu","t":"Зачекай... Ти сказала «Фавія»?"}]},{"id":"hemma_09","i":9,"title":"Замок з привидами","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"hemma","t":"Яке чудове місце з привидами."},{"a":"lilu","t":"Воно жахливе. Кожен, хто має здоровий глузд, повинен обходити його десятою дорогою."},{"a":"lilu","t":"Але найголовніше те, що за результатами моїх досліджень..."},{"a":"lilu","t":"...кілька століть тому тут правив божевільний король з роду Фавіїв."},{"a":"lilu","t":"Може, Клод — його далекий родич? Сподіваюся, він жодним чином не пов'язаний із занепадом того королівства..."},{"a":"hemma","t":"...Ми відчуваємо. У нас є зв'язок із цим місцем. Це воно."},{"a":"hemma","t":"Ми у великому боргу перед тобою, Лілу. Але тепер ти маєш нас залишити."},{"a":"lilu","t":"Хеммо... Бажаю успіху!"}]},{"id":"hemma_10","i":10,"title":"Поки смерть не розлучить нас","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"hemma","t":"Темне глухе місце з привидами, наповнене некромантичною енергією..."},{"a":"hemma","t":"Як довго ми його шукали!"},{"a":"hemma","t":"А тепер потрібно знайти підхожу ємність..."},{"a":"hemma","t":"Можеш нічого не говорити. Ми й так знаємо, чого ти хочеш."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"...Обладунки найбожевільнішого короля, назавжди прив'язані до цього місця."},{"a":"hemma","t":"<c1>Зрощення душі!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Ох... Ми відчуваємо... Чи я?.."},{"a":"hemma","t":"Я вже й забула, як це — відчувати лише себе..."},{"a":"hemma","t":"Я страждала цілу вічність, щоб урятувати тебе, мій милий. Бо знаю, що ти вчинив би так само."},{"a":"hemma","t":"Сюди обов'язково прийдуть сміливі шукачі пригод. Борися з ними й у кривавій бійні зціли свою змучену душу."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Прощавай, коханий. Але лише смерть нас розлучить по-справжньому."}]},{"id":"hemma_epilogue","i":11,"title":"Епілог","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>БОВДУРИ!!! ЯК ВИ НАВАЖИЛИСЯ СТУПИТИ НА МОЇ ЗЕМЛІ?</c4>"},{"a":"sia","t":"...Який уїдливий ворог!"},{"a":"Castle_Boss","t":"<c4>А-ХА-ХА! ЖАЛЮГІДНІ СМЕРТНІ!</c4>"},{"a":"argon","t":"Пані Сіє! Рудо! Ми маємо відступити!"},{"a":"rudo","t":"Ніколи! Я не відступлю ні на крок!"},{"a":"yami","t":"Я знайшла вихід. Швидше!"},{"a":"rudo","t":"Я ще повернуся, велетенська шкарабанко! Чуєш мене?"},{"a":"Castle_Boss","t":"<c4>ПОВЕРТАЙТЕСЯ, КОЛИ БУДЕТЕ ЗДАТНІ БИТИСЯ!</c4>"},{"a":"Castle_Boss","t":"<c4>ПЕРЕКАЖІТЬ СВОЇМ НАЙКРАЩИМ ГЕРОЯМ, ЩО КОРОЛЬ-ТИРАН ЧЕКАЄ!</c4>"}]}]},{"id":"yami","name":"Ямі","chapters":[{"id":"yami_01","i":1,"title":"Азумська мандрівниця","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Хі-хі-хі! Що в нас тут?"},{"a":"yami","t":"Пф. Зникни звідси."},{"a":"monster_forest_Boss","t":"Геть погані манери, панночко! І одяг якийсь дивний!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Відчуваю дух Азуми, східного королівства людей!"},{"a":"monster_forest_Boss","t":"Чого тобі тут потрібно, панночко?"},{"a":"monster_forest_Boss","t":"Зброї до біса, а слів небагато... Певно, ти вбивця, га?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Хі-хі! Так і знав! Дурні люди, завжди вбивають одне одного!"},{"a":"yami","t":"...Ти правий. Я прибула сюди, щоб убити короля-тирана."},{"a":"monster_forest_Boss","t":"Отакої! Що ти за вбивця така, коли всім про це базікаєш? Навіщо мені сказала?"},{"a":"yami","t":"Тому що ти вже нікому про це не розкажеш. Бувай."},{"a":"monster_forest_Boss","t":"Ай!"},{"a":"yami","t":"...Королю Рейнгольде, ти наступний."}]},{"id":"yami_02","i":2,"title":"Хто мисливець, а хто здобич","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"yami","t":"...Цей замок непогано охороняється."},{"a":"yami","t":"Система паролів щоденно змінюється..."},{"a":"yami","t":"Варта патрулює не за графіком..."},{"a":"yami","t":"Мені треба бути..."},{"a":"argon","t":"Гей, привіт! Ти, у кущах!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Ти також хочеш стати лицарем?"},{"a":"argon","t":"Сія скоро з'явиться! Не треба ховатися, вона досить гарна!"},{"a":"yami","t":"Сіє!.."},{"a":"yami","t":"Мені треба йти. Бувай."},{"a":"argon","t":"С-стій!"},{"a":"argon","t":"Ого! Димова бомба?!"},{"a":"yami","t":"...Здається, утратила цього дурня."},{"a":"yami","t":"Якщо Сія тут... Моє завдання буде нелегким."},{"a":"yami","t":"Але його треба виконати. Я мушу."},{"a":"yami","t":"Заради ордена... та моєї сестри."}]},{"id":"yami_03","i":3,"title":"Перелом","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"king","t":"Поважні люди мого королівства! Дякую вам, що прийшли на мій розкішний бенкет!"},{"a":"king","t":"Для вас це чудова нагода на власні очі побачити мою прекрасну особу! Не втрачайте шансу!"},{"a":"yami","t":"(Пихатий тиран. Типовий.)"},{"a":"sia","t":"Ммм, так. Дякуємо за цю повчальну промову, Ваша Величносте."},{"a":"sia","t":"Ми зібрали вас тут сьогодні, щоб відсвяткувати неймовірну щедрість короля."},{"a":"sia","t":"За останні місяці він пожертвував кілька мільйонів золотом з власної скарбниці..."},{"a":"sia","t":"...кільком місцевим храмам, школам і притулкам."},{"a":"sia","t":"Усіх запрошуємо до участі, розкажіть своїм друзям і рідним."},{"a":"sia","t":"Слава королю Рейнгольду!"},{"a":"yami","t":"(...Тирани так не роблять)"},{"a":"yami","t":"(...Але ж орден не міг збрехати. Це якийсь маневр.)"},{"a":"yami","t":"Тиране Рейнгольде, настав кінець твоєму правлінню!"},{"a":"sia","t":"Сюрікен...! Азумська вбивця!"},{"a":"yami","t":"Я не влучила...?! Не може бути!"},{"a":"sia","t":"Охорона! Перекрити всі виходи! Негайно схопіть цю жінку!"}]},{"id":"yami_04","i":4,"title":"Відбиття","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"yami","t":"(Я вагалася... І не влучила.)"},{"a":"yami","t":"(Чи міг орден збрехати?)"},{"a":"yami","t":"(Не має значення. Зараз я сама.)"},{"a":"argon","t":"Нарешті я тебе знайшов!"},{"a":"yami","t":"Дурний лицар!"},{"a":"argon","t":"Стій, я тут не для того, щоб битися!"},{"a":"yami","t":"Я не повірю твоїм хитрощам, рейнгольдовський псе!"},{"a":"argon","t":"...Ти ж навмисно не поцілила, так?"},{"a":"yami","t":"...!"},{"a":"argon","t":"Я бачив тебе на бенкеті. Я бачив, як тобі було шкода, що ти кинула той сюрікен."},{"a":"argon","t":"Розумієш, король — непогана людина. Він іноді дивакуватий, але він робить усе, що може!"},{"a":"argon","t":"Не знаю, хто тобі за це заплатив, але вони точно погані хлопці..."},{"a":"argon","t":"Давай ти повернешся до замку й вибачишся? Я впевнений, що Рейнгольд..."},{"a":"yami","t":"Вибачитися? Яка дурня."},{"a":"yami","t":"Мені треба подумати. Не йди за мною, якщо хочеш жити."},{"a":"argon","t":"...Я впевнений, що вона непогана людина."},{"a":"argon","t":"Тепер треба доповісти Сії..."},{"a":"argon","t":"Ох і отримаю ж я зараз..."}]},{"id":"yami_05","i":5,"title":"При світі місяця","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Сонячне світло у верхівці верби, відлуння минулих днів<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Посеред галявини ельфів ми... ой!"},{"a":"yami","t":"Холод, який ти відчуваєш, — це моє лезо на твоїй шиї."},{"a":"yami","t":"У мене є запитання. Якщо твої відповіді будуть чесними, ти будеш жити."},{"a":"fabric","t":"А-а-а! З-звичайно! Усе, що... Ой!"},{"a":"yami","t":"Тихо."},{"a":"yami","t":"Дурень, якого ти кличеш королем... Розкажи мені про нього."},{"a":"fabric","t":"К-король Рейнгольд? Він правитель цих земель..."},{"a":"fabric","t":"Хоча він трохи ексцентричний, йому не бракує чеснот і щедрості."},{"a":"fabric","t":"...А ось чого йому бракує — це досвіду. Його нова радниця Сія повністю це компенсує!"},{"a":"yami","t":"Неймовірно!.. Від твоїх слів тхне боягузтвом, але вони схожі на правду."},{"a":"yami","t":"У цьому місті є оракул?"},{"a":"fabric","t":"А, так! Ельфійка Серена, он там на горі!"},{"a":"fabric","t":"Таємнича незнайомка! Чи можу я мати честь дізнатися ваше ім... Ой!"},{"a":"yami","t":"Кілька днів тому я б убила тебе, не замислюючись. Не провокуй долю."},{"a":"yami","t":"Повертайся до свого нудного життя та забудь про все, що тут відбувалося."},{"a":"fabric","t":"...Ох! Яка п'янка зустріч!"},{"a":"fabric","t":"Діва в чорному... Чи зустрінемося ми знов, хотів би я знати..."}]},{"id":"yami_06","i":6,"title":"Зламаний пішак","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"mana","t":"...Чорний вітер видає присутність Переслідувача."},{"a":"yami","t":"...! Як?.."},{"a":"mana","t":"Та, Хто Переслідує, ступає легко, наче перо, але третє око бачить важке серце."},{"a":"yami","t":"...Досить ребусів, оракул. Мені потрібні відповіді."},{"a":"yami","t":"Стосовно ордену... Моєї родини."},{"a":"mana","t":"Торговець смертю потребує вказівок. Що воно пропонує натомість?"},{"a":"yami","t":"Твоє життя."},{"a":"mana","t":"...Нехай так і буде."},{"a":"mana","t":"<c1>Колись Азумський орден займався виправленням несправедливості...</c1>"},{"a":"mana","t":"<c1>...Захисники ордену перетворилися на рабів багатіїв...</c1>"},{"a":"mana","t":"<c1>...Заради нездійсненної мети жертвою став пішак...</c1>"},{"a":"mana","t":"<c1>...Чи то успіх, чи то невдача, орден залишається переможцем.</c1>"},{"a":"yami","t":"...Неймовірно."},{"a":"mana","t":"Посланець закінчив говорити."},{"a":"yami","t":"...НЕЙМОВІРНО!"},{"a":"mana","t":"..."},{"a":"mana","t":"Той, хто крадеться в тіні, із часом має домовитися зі світлом."}]},{"id":"yami_07","i":7,"title":"Бийся або бійся","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"yami","t":"...Мені треба зібрати речі та йти якомога швидше."},{"a":"inn","t":"Гей, таємнича незнайомко."},{"a":"yami","t":"Корчмаре. Я тобі заплатила за мовчання."},{"a":"inn","t":"Не турбуйся, ми тут у корчмі «Смарагд» не ставимо зайвих запитань!"},{"a":"inn","t":"Проте в нас тут є кілька відвідувачів, які, схоже, шукають тебе. Виглядають не дуже."},{"a":"yami","t":"(Доглядачі від ордену? Так швидко?)"},{"a":"inn","t":"Вони не назвалися. Якісь підозрілі. Твої друзі?"},{"a":"yami","t":"Уже ні. Скажи їм, що я загинула. Я б могла."},{"a":"inn","t":"Хутко зникаєш? Я так і думав. Приготував для тебе дещо."},{"a":"yami","t":"...Дякую, корчмаре. Але там, куди я йду, це не знадобиться."}]},{"id":"yami_08","i":8,"title":"Подорож в один кінець","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"На пік Похмурий Шпиль, кажеш?"},{"a":"wood","t":"Так, я бачила схожу на ніндзя дівчину, схожу на твій опис. Здається, вона поспішала."},{"a":"sia","t":"Чудово. Нарешті ми відстежили нашу вбивцю."},{"a":"sia","t":"Я зберу патруль і..."},{"a":"wood","t":"Ти впевнена? Не думаю, що це так необхідно."},{"a":"sia","t":"...Чому б і ні, Горзо?"},{"a":"wood","t":"Похід на пік Похмурий Шпиль наодинці — це самогубство. Ця дівчина навіть не взяла із собою жодних припасів."},{"a":"wood","t":"Вона не може цього не знати. Навіть Рудо не такий дурний, щоб іти туди наодинці."},{"a":"sia","t":"Ось як? Дякую, Горзо. Прийму це до уваги."},{"a":"sia","t":"Думаю, проблема вирішиться сама по собі, але..."},{"a":"sia","t":"Залишився якийсь гіркий осад. Про що думаєш, убивця?"}]},{"id":"yami_09","i":9,"title":"Зіткнення на Похмурому Шпилі (Ямі)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"argon","t":"Мабуть, це доля. Це доручення навіть краще за гарпію!"},{"a":"yami","t":"...Давай. Я вб'ю тебе просто на місці."},{"a":"argon","t":"Не чую впевненості у твоїх словах..."},{"a":"yami","t":"...Ти правий, мене більше нічого не цікавить."},{"a":"yami","t":"Якщо ти насправді хочеш моєї смерті, залиш мене помирати тут."},{"a":"argon","t":"Я б нікого не залишив помирати! Я відведу тебе до короля Рейнгольда!"},{"a":"argon","t":"Я знаю, що він зрозуміє! Якщо знадобиться, я тебе віднесу!"},{"a":"yami","t":"..."},{"a":"argon","t":"Ну ж бо, оп!"},{"a":"argon","t":"Тримайся, шкіро та кості! Коли ти взагалі востаннє їла?"},{"a":"yami","t":"..."},{"a":"argon","t":"Поїж, коли будеш повертатися, шлях буде нелегким!"}]},{"id":"yami_10","i":10,"title":"У тилу ворога","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Охорона! Приведіть підкріплення та спостерігайте за кожним її рухом!"},{"a":"sia","t":"Аргоне, почекай за дверима, поки ми поговоримо про це із... цим незваним гостем."},{"a":"argon","t":"Зрозуміло!"},{"a":"sia","t":"Що ж. Розповідай, убивце."},{"a":"yami","t":"Пф, саме так. Мене найняли, щоб убити тирана."},{"a":"yami","t":"Чи я так думала. Здається, він просто добродушний блазень."},{"a":"king","t":"Б-блазень?!"},{"a":"sia","t":"Що ваш народ має проти нашого короля?"},{"a":"yami","t":"Мій орден наносить удари лише в ім'я справедливості..."},{"a":"yami","t":"Але схоже на те, що то була брехня. А через мою похибку на мене тепер також відкрите полювання."},{"a":"yami","t":"Я... перепрошую. Я понесу справедливе... покарання..."},{"a":"yami","t":"...Ух."},{"a":"king","t":"Вона впала!"},{"a":"sia","t":"Від утоми й голоду..."},{"a":"sia","t":"Охороно! Покличте найкращих лікарів до її ліжка!"},{"a":"sia","t":"Поводьтеся з нею, як з королівською гостею."}]},{"id":"yami_epilogue","i":11,"title":"Епілог","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Діаманти"},"side":false,"lines":[{"a":"sia","t":"Уф... уф... Як же високо... до тебе повзти..."},{"a":"yami","t":"Тепер тут мій дім."},{"a":"sia","t":"Чому б не оселитися всередині міста? Тебе вибачили."},{"a":"yami","t":"Імовірно, мій клан вважає мене мертвою. Я б хотіла, щоб так і залишилося."},{"a":"sia","t":"Я розумію. Я проконтролюю, щоб ти регулярно отримувала припаси."},{"a":"sia","t":"А тепер стосовно твого нового завдання..."},{"a":"yami","t":"Знову бандити в імперії?"},{"a":"sia","t":"Саме так. Як тобі відомо, Його Величність викликає лють заздрісників."},{"a":"sia","t":"Дивись цей документ, щоб дізнатися про свої цілі."},{"a":"yami","t":"Буде зроблено."},{"a":"sia","t":"Важко це казати, але я тобі вірю."},{"a":"sia","t":"Мені треба повертатися. Хоча не скажу, що з нетерпінням чекаю прогулянки..."},{"a":"yami","t":"Сіє... Рейнгольд..."},{"a":"yami","t":"...Дякую. Справді."}]}]}];
